/* ĐỌC HIỂU — dữ liệu bài đọc (v145, nội dung tự soạn) */
const RD_LESSONS = [{"id":"a1-family","lv":1,"icon":"👨‍👩‍👧","t":"My Family","vi":"Gia đình tôi","topic":"Đời sống","p":["My name is Linh. I am twenty years old and I live in Hue with my family. There are five people in my family: my father, my mother, my brother, my grandmother and me.","My father is a teacher. He teaches maths at a high school. My mother works in a bank. My brother Minh is twelve. He likes football and computer games.","My grandmother is seventy. She cooks very well, and every Sunday she makes a big lunch for us. I love my family very much."],"g":[["grandmother","bà"],["teacher","giáo viên"],["high school","trường cấp ba"],["bank","ngân hàng"],["cook","nấu ăn"],["lunch","bữa trưa"]],"q":[{"k":"mc","q":"How many people are there in Linh's family?","o":["Four","Five","Six"],"a":1,"e":"Bài viết: “There are five people in my family”.","ev":"There are five people in my family"},{"k":"mc","q":"What does Linh's father do?","o":["He works in a bank.","He is a teacher.","He is a cook."],"a":1,"e":"Câu “My father is a teacher” cho biết bố Linh là giáo viên.","ev":"My father is a teacher."},{"k":"tf","q":"Linh's brother is older than Linh.","a":1,"e":"Linh 20 tuổi, còn Minh 12 tuổi, nên anh ấy nhỏ tuổi hơn Linh. Câu này Sai.","ev":"My brother Minh is twelve."},{"k":"tf","q":"Linh's grandmother cooks lunch every Sunday.","a":0,"e":"“every Sunday she makes a big lunch for us” → Đúng.","ev":"every Sunday she makes a big lunch for us"},{"k":"mc","q":"What does Minh like?","o":["Maths and books","Cooking","Football and computer games"],"a":2,"e":"“He likes football and computer games.”","ev":"He likes football and computer games."}]},{"id":"a1-day","lv":1,"icon":"⏰","t":"A Day in My Life","vi":"Một ngày của tôi","topic":"Đời sống","p":["I usually get up at six o'clock. I wash my face, brush my teeth and have breakfast with my sister. We often eat bread and drink milk.","I go to work by motorbike. My office is not far from my house, so it takes only fifteen minutes. I start work at eight and finish at five.","In the evening, I cook dinner and watch TV. Sometimes I read a book or call my friends. I go to bed at about eleven."],"g":[["get up","thức dậy"],["brush my teeth","đánh răng"],["breakfast","bữa sáng"],["office","văn phòng"],["far","xa"],["go to bed","đi ngủ"]],"q":[{"k":"mc","q":"What time does the writer usually get up?","o":["At five","At six","At eight"],"a":1,"e":"“I usually get up at six o'clock.”","ev":"I usually get up at six o'clock."},{"k":"mc","q":"How does the writer go to work?","o":["By bus","On foot","By motorbike"],"a":2,"e":"“I go to work by motorbike.”","ev":"I go to work by motorbike."},{"k":"tf","q":"The office is far from the writer's house.","a":1,"e":"Bài viết nói “My office is not far from my house” (không xa) → Sai.","ev":"My office is not far from my house"},{"k":"tf","q":"The writer works for nine hours a day.","a":0,"e":"Bắt đầu lúc 8 giờ, kết thúc lúc 5 giờ chiều: 8 → 17 là 9 tiếng → Đúng.","ev":"I start work at eight and finish at five."},{"k":"mc","q":"What does the writer NOT do in the evening?","o":["Cook dinner","Go to the gym","Watch TV"],"a":1,"e":"Buổi tối người viết nấu ăn, xem TV, đọc sách, gọi bạn. Không có đi tập gym.","ev":"In the evening, I cook dinner and watch TV."}]},{"id":"a1-market","lv":1,"icon":"🧺","t":"At the Market","vi":"Ở chợ","topic":"Mua sắm","p":["Every Saturday morning, Mai goes to the market near her house. The market is busy and noisy, but she likes it because the food is fresh and cheap.","Today she buys two kilos of rice, some fish and a bag of oranges. The oranges are sweet. She also wants some tomatoes, but they are very expensive today, so she does not buy them.","Mai pays the sellers with cash. She walks home happily and cooks a nice lunch."],"g":[["market","chợ"],["busy","đông đúc"],["noisy","ồn ào"],["fresh","tươi"],["cheap","rẻ"],["expensive","đắt"],["cash","tiền mặt"]],"q":[{"k":"mc","q":"When does Mai go to the market?","o":["Every Saturday morning","Every evening","Every Sunday afternoon"],"a":0,"e":"“Every Saturday morning, Mai goes to the market…”","ev":"Every Saturday morning, Mai goes to the market near her house."},{"k":"mc","q":"Why does Mai like the market?","o":["It is quiet.","The food is fresh and cheap.","It is near her office."],"a":1,"e":"“she likes it because the food is fresh and cheap”.","ev":"she likes it because the food is fresh and cheap"},{"k":"tf","q":"Mai buys some tomatoes today.","a":1,"e":"Cà chua hôm nay đắt nên “she does not buy them” → Sai.","ev":"so she does not buy them"},{"k":"tf","q":"The oranges are sweet.","a":0,"e":"“The oranges are sweet.” → Đúng.","ev":"The oranges are sweet."},{"k":"mc","q":"How does Mai pay?","o":["By card","With her phone","With cash"],"a":2,"e":"“Mai pays the sellers with cash.”","ev":"Mai pays the sellers with cash."}]},{"id":"a1-room","lv":1,"icon":"🛏️","t":"My Room","vi":"Căn phòng của tôi","topic":"Nhà cửa","p":["This is my room. It is small, but it is clean and bright. There is a big window next to my bed, so I can see the trees outside.","There is a desk under the window. On the desk, there is a computer, a lamp and some books. I study and work at this desk every day.","My clothes are in a brown wardrobe. On the wall, there are two photos of my family and a map of Viet Nam. My room is my favourite place in the house."],"g":[["bright","sáng sủa"],["window","cửa sổ"],["desk","bàn làm việc"],["lamp","đèn bàn"],["wardrobe","tủ quần áo"],["wall","bức tường"],["favourite","yêu thích nhất"]],"q":[{"k":"tf","q":"The room is big.","a":1,"e":"“It is small, but it is clean and bright.” → phòng nhỏ → Sai.","ev":"It is small, but it is clean and bright."},{"k":"mc","q":"Where is the desk?","o":["Next to the door","Under the window","Behind the bed"],"a":1,"e":"“There is a desk under the window.”","ev":"There is a desk under the window."},{"k":"mc","q":"What is NOT on the desk?","o":["A lamp","A computer","A TV"],"a":2,"e":"Trên bàn có máy tính, đèn và sách. Không có TV.","ev":"there is a computer, a lamp and some books"},{"k":"mc","q":"What is on the wall?","o":["Two photos and a map","A clock and a mirror","A big window only"],"a":0,"e":"“there are two photos of my family and a map of Viet Nam”.","ev":"there are two photos of my family and a map of Viet Nam"},{"k":"tf","q":"The writer likes this room more than other places in the house.","a":0,"e":"“My room is my favourite place in the house.” → Đúng.","ev":"My room is my favourite place in the house."}]},{"id":"a1-weekend","lv":1,"icon":"🌳","t":"A Weekend in the Park","vi":"Cuối tuần ở công viên","topic":"Giải trí","p":["On Sundays, Nam and his friends often go to the park in the city centre. They meet at the gate at seven in the morning, when the weather is cool.","First they run around the lake for thirty minutes. Then they sit under a big tree and drink coconut water. Nam's friend Lan always brings a camera and takes photos of birds and flowers.","At about nine o'clock, the park gets hot and crowded, so they go to a small café for breakfast."],"g":[["city centre","trung tâm thành phố"],["gate","cổng"],["cool","mát mẻ"],["lake","hồ"],["coconut water","nước dừa"],["crowded","đông người"]],"q":[{"k":"mc","q":"Where do Nam and his friends meet?","o":["At a café","At the park gate","At Nam's house"],"a":1,"e":"“They meet at the gate at seven in the morning”.","ev":"They meet at the gate at seven in the morning"},{"k":"mc","q":"What do they do first?","o":["Have breakfast","Take photos","Run around the lake"],"a":2,"e":"“First they run around the lake for thirty minutes.”","ev":"First they run around the lake for thirty minutes."},{"k":"tf","q":"Lan takes photos of birds and flowers.","a":0,"e":"“Lan always brings a camera and takes photos of birds and flowers.” → Đúng.","ev":"takes photos of birds and flowers"},{"k":"tf","q":"The park is quiet at nine o'clock.","a":1,"e":"Lúc 9 giờ “the park gets hot and crowded” (nóng và đông) → Sai.","ev":"the park gets hot and crowded"},{"k":"mc","q":"Why do they go to the park early?","o":["Because the weather is cool","Because the café opens early","Because Lan works at nine"],"a":0,"e":"Họ gặp lúc 7 giờ “when the weather is cool” (khi trời còn mát).","ev":"when the weather is cool"}]},{"id":"a1-message","lv":1,"icon":"✉️","t":"A Message to a Friend","vi":"Tin nhắn cho bạn","topic":"Giao tiếp","p":["Hi Hoa,","How are you? I am in Da Nang with my cousin this week. The weather is sunny and the beach is beautiful. We swim in the sea every morning and eat seafood in the evening.","I come back to Ha Noi on Friday. Are you free on Saturday? Let's have coffee at our usual place at ten. Please text me.","See you soon,\nTrang"],"g":[["cousin","anh / chị / em họ"],["sunny","nắng"],["beach","bãi biển"],["seafood","hải sản"],["free","rảnh"],["usual","quen thuộc, như mọi khi"],["text","nhắn tin"]],"q":[{"k":"mc","q":"Where is Trang this week?","o":["In Ha Noi","In Da Nang","In Hue"],"a":1,"e":"“I am in Da Nang with my cousin this week.”","ev":"I am in Da Nang with my cousin this week."},{"k":"tf","q":"It is raining in Da Nang.","a":1,"e":"“The weather is sunny” (trời nắng) → Sai.","ev":"The weather is sunny"},{"k":"mc","q":"When does Trang go back to Ha Noi?","o":["On Friday","On Saturday","On Sunday"],"a":0,"e":"“I come back to Ha Noi on Friday.”","ev":"I come back to Ha Noi on Friday."},{"k":"mc","q":"What does Trang want to do with Hoa?","o":["Go swimming","Eat seafood","Have coffee"],"a":2,"e":"“Let's have coffee at our usual place at ten.”","ev":"Let's have coffee at our usual place at ten."},{"k":"tf","q":"Trang asks Hoa to send her a message.","a":0,"e":"“Please text me.” = hãy nhắn tin cho tôi → Đúng.","ev":"Please text me."}]},{"id":"a2-trip","lv":2,"icon":"🏔️","t":"A Trip to Sa Pa","vi":"Chuyến đi Sa Pa","topic":"Du lịch","p":["Last December, my friends and I took a night bus from Ha Noi to Sa Pa. The journey took about six hours, and we arrived early in the morning. It was very cold, only five degrees, so we bought warm hats at the bus station.","On the first day, we walked through the rice terraces and visited a small village. A local woman showed us how to make colourful cloth. She was very friendly and patient, even though our questions were silly.","The next day, we wanted to climb Fansipan, but it was too foggy. Instead, we stayed in a café, drank hot ginger tea and played cards. In the evening, we tried grilled food at the night market.","The trip was short, but it was one of the best holidays I have ever had. I want to go back in spring, when the flowers are blooming."],"g":[["journey","chuyến đi, hành trình"],["rice terraces","ruộng bậc thang"],["village","làng, bản"],["local","người địa phương"],["patient","kiên nhẫn"],["foggy","nhiều sương mù"],["instead","thay vào đó"],["bloom","nở hoa"]],"q":[{"k":"mc","q":"How did the writer travel to Sa Pa?","o":["By train","By night bus","By plane"],"a":1,"e":"“we took a night bus from Ha Noi to Sa Pa”.","ev":"took a night bus from Ha Noi to Sa Pa"},{"k":"mc","q":"Why did they buy hats?","o":["Because it was very cold","Because the hats were cheap","Because it was sunny"],"a":0,"e":"Trời chỉ 5 độ, “so we bought warm hats”.","ev":"It was very cold, only five degrees, so we bought warm hats at the bus station."},{"k":"tf","q":"The writer climbed Fansipan on the second day.","a":1,"e":"Họ muốn leo nhưng “it was too foggy” và ở lại quán cà phê → Sai.","ev":"we wanted to climb Fansipan, but it was too foggy"},{"k":"mc","q":"What did the local woman do?","o":["She sold them tea.","She drove the bus.","She showed them how to make cloth."],"a":2,"e":"“A local woman showed us how to make colourful cloth.”","ev":"A local woman showed us how to make colourful cloth."},{"k":"tf","q":"The writer would like to visit Sa Pa again.","a":0,"e":"“I want to go back in spring” → Đúng.","ev":"I want to go back in spring"}]},{"id":"a2-job","lv":2,"icon":"💼","t":"My First Job","vi":"Công việc đầu tiên","topic":"Công việc","p":["When I was nineteen, I got my first job as a waiter in a busy restaurant. I worked four evenings a week after university. The pay was not very high, but I needed money for my books and rent.","At first, the job was really difficult. I often forgot what customers ordered, and once I dropped a plate of noodles on the floor. My manager, Mr Tuan, did not get angry. He told me to write every order in a small notebook.","After a few weeks, I became faster and more confident. I learned how to talk politely to customers, how to work in a team and how to stay calm when the restaurant was full.","I left the job after a year, but I still use those skills today in my office job."],"g":[["waiter","người phục vụ bàn"],["pay","tiền lương"],["rent","tiền thuê nhà"],["customer","khách hàng"],["order","gọi món; món đã gọi"],["confident","tự tin"],["politely","một cách lịch sự"],["calm","bình tĩnh"]],"q":[{"k":"mc","q":"Why did the writer need the job?","o":["To buy a motorbike","To pay for books and rent","To travel abroad"],"a":1,"e":"“I needed money for my books and rent.”","ev":"I needed money for my books and rent."},{"k":"tf","q":"The writer worked every evening.","a":1,"e":"Chỉ “four evenings a week” (4 tối một tuần) → Sai.","ev":"I worked four evenings a week after university."},{"k":"mc","q":"How did Mr Tuan react when the writer made mistakes?","o":["He got angry.","He gave useful advice.","He asked him to leave."],"a":1,"e":"Ông không giận mà khuyên ghi mọi món vào sổ: “He told me to write every order in a small notebook.”","ev":"He told me to write every order in a small notebook."},{"k":"mc","q":"Which skill did the writer NOT mention learning?","o":["Working in a team","Speaking politely","Cooking noodles"],"a":2,"e":"Người viết học nói lịch sự, làm việc nhóm, giữ bình tĩnh. Không nói về nấu mì.","ev":"I learned how to talk politely to customers, how to work in a team and how to stay calm"},{"k":"tf","q":"The writer still works at the restaurant.","a":1,"e":"“I left the job after a year” → đã nghỉ → Sai.","ev":"I left the job after a year"}]},{"id":"a2-phone","lv":2,"icon":"📱","t":"Too Much Phone?","vi":"Dùng điện thoại quá nhiều?","topic":"Sức khỏe","p":["Quang is a student, and he loves his smartphone. He uses it to chat with friends, watch videos and play games. Last month, he checked his screen time and was shocked: he used his phone for almost seven hours every day.","He also noticed some problems. He often went to bed after midnight, his eyes felt tired, and he could not focus in class. His grades were getting worse.","So Quang made some simple rules. He turned off notifications from social media and put his phone in another room when he studied. He also stopped using it one hour before bed and read a paper book instead.","Two weeks later, he was sleeping better and felt less stressed. He still uses his phone every day, but now he controls it, not the other way round."],"g":[["screen time","thời gian dùng màn hình"],["shocked","sửng sốt"],["notice","nhận ra"],["focus","tập trung"],["grades","điểm số"],["notifications","thông báo"],["stressed","căng thẳng"],["the other way round","ngược lại"]],"q":[{"k":"mc","q":"How long did Quang use his phone every day?","o":["About two hours","Almost seven hours","More than ten hours"],"a":1,"e":"“he used his phone for almost seven hours every day.”","ev":"he used his phone for almost seven hours every day"},{"k":"mc","q":"Which problem is mentioned in the text?","o":["He lost his phone.","His eyes felt tired.","He argued with his parents."],"a":1,"e":"“his eyes felt tired” là một trong các vấn đề.","ev":"his eyes felt tired"},{"k":"tf","q":"Quang put his phone in another room when he studied.","a":0,"e":"“put his phone in another room when he studied” → Đúng.","ev":"put his phone in another room when he studied"},{"k":"tf","q":"Quang stopped using his phone completely.","a":1,"e":"“He still uses his phone every day” → vẫn dùng → Sai.","ev":"He still uses his phone every day"},{"k":"mc","q":"What is the main idea of the text?","o":["Phones are bad and we should not use them.","Simple rules helped Quang control his phone use.","Quang wants to buy a new phone."],"a":1,"e":"Bài kể chuyện Quang đặt vài quy tắc đơn giản và kiểm soát được việc dùng điện thoại.","ev":"now he controls it, not the other way round"}]},{"id":"a2-recipe","lv":2,"icon":"🍲","t":"Grandma's Pho","vi":"Món phở của bà","topic":"Ẩm thực","p":["My grandmother makes the best pho in our town. She learned the recipe from her mother more than fifty years ago, and she never writes it down.","The secret is the broth. She starts early in the morning, often at four o'clock. She cooks beef bones for many hours with onion, ginger, star anise and cinnamon. Every hour, she removes the fat from the top so the soup stays clear.","While the broth is cooking, she slices the beef very thinly and prepares fresh herbs. When the family arrives, she puts the noodles and beef in big bowls and pours the hot broth over them.","Last summer I asked her to teach me. My first pho was too salty, but she laughed and said, \"Good cooks are made, not born.\""],"g":[["recipe","công thức nấu ăn"],["broth","nước dùng"],["bones","xương"],["remove","loại bỏ, vớt ra"],["fat","mỡ"],["slice","thái lát"],["herbs","rau thơm"],["pour","rót, chan"]],"q":[{"k":"mc","q":"Where did the grandmother learn the recipe?","o":["From a cookbook","From her mother","From a restaurant"],"a":1,"e":"“She learned the recipe from her mother”.","ev":"She learned the recipe from her mother"},{"k":"mc","q":"According to the text, what is the secret of her pho?","o":["The noodles","The herbs","The broth"],"a":2,"e":"“The secret is the broth.”","ev":"The secret is the broth."},{"k":"tf","q":"She removes the fat so that the soup stays clear.","a":0,"e":"“she removes the fat from the top so the soup stays clear” → Đúng.","ev":"she removes the fat from the top so the soup stays clear"},{"k":"tf","q":"The writer's first pho was perfect.","a":1,"e":"“My first pho was too salty” (quá mặn) → Sai.","ev":"My first pho was too salty"},{"k":"mc","q":"\"Good cooks are made, not born\" means…","o":["You become a good cook by practising.","Only some people can cook.","Cooking is easy for everyone."],"a":0,"e":"Câu nói nghĩa là đầu bếp giỏi là do luyện tập mà thành, không phải sinh ra đã giỏi.","ev":"Good cooks are made, not born."}]},{"id":"a2-neighbour","lv":2,"icon":"🏘️","t":"A Helpful Neighbour","vi":"Người hàng xóm tốt bụng","topic":"Đời sống","p":["Mrs Hanh lives next door to us. She is about sixty-five and lives alone with her cat, Mun. Her children work in Ho Chi Minh City, so they only visit her at Tet.","Last month, my parents went away for a week and I stayed at home alone for the first time. On the second night, there was a big storm and the electricity went off. I was a little scared, so I knocked on Mrs Hanh's door.","She gave me a candle and a hot bowl of rice soup, and we talked until the power came back. She told me funny stories about our street forty years ago, when there were rice fields instead of houses.","Now I visit her every weekend. I help her carry heavy shopping bags, and she teaches me how to grow vegetables on the roof."],"g":[["next door","nhà bên cạnh"],["alone","một mình"],["storm","cơn bão"],["electricity","điện"],["scared","sợ"],["knock","gõ cửa"],["candle","cây nến"],["grow","trồng"]],"q":[{"k":"mc","q":"Who lives with Mrs Hanh?","o":["Her children","Nobody, only her cat","Her sister"],"a":1,"e":"“lives alone with her cat, Mun” → sống một mình với con mèo.","ev":"lives alone with her cat, Mun"},{"k":"tf","q":"Mrs Hanh's children visit her every month.","a":1,"e":"“they only visit her at Tet” (chỉ về thăm dịp Tết) → Sai.","ev":"they only visit her at Tet"},{"k":"mc","q":"Why did the writer go to Mrs Hanh's house?","o":["To borrow some rice","Because there was a storm and no electricity","To give her a present"],"a":1,"e":"Có bão lớn và mất điện, người viết thấy sợ nên sang gõ cửa.","ev":"there was a big storm and the electricity went off"},{"k":"mc","q":"What was the street like forty years ago?","o":["It had rice fields.","It had many shops.","It was a big market."],"a":0,"e":"“there were rice fields instead of houses”.","ev":"when there were rice fields instead of houses"},{"k":"tf","q":"Mrs Hanh teaches the writer to grow vegetables.","a":0,"e":"“she teaches me how to grow vegetables on the roof” → Đúng.","ev":"she teaches me how to grow vegetables on the roof"}]},{"id":"a2-3d","lv":2,"icon":"🧊","t":"Learning 3D at Home","vi":"Tự học 3D ở nhà","topic":"Công nghệ","p":["Duc works in a shoe shop, but in his free time he loves making 3D models on his computer. He started two years ago after watching a video about how animators make cartoon characters.","At the beginning, everything was confusing. The software had hundreds of buttons, and his first model, a simple cup, looked more like a strange rock. But he did not give up. Every night he practised for one hour and followed free lessons online.","Slowly he got better. He learned how to build clean shapes, add colours and textures, and set up lights. Last month he finished a small game character, a cute robot with big eyes, and shared it on a website for artists.","Many people liked his work, and a small game company sent him a message. Next week, Duc has his first interview for a job as a 3D artist."],"g":[["free time","thời gian rảnh"],["animator","họa sĩ hoạt hình"],["confusing","khó hiểu, rối"],["software","phần mềm"],["give up","bỏ cuộc"],["texture","texture, ảnh bề mặt"],["share","chia sẻ"],["interview","buổi phỏng vấn"]],"q":[{"k":"mc","q":"What is Duc's job now?","o":["He is a 3D artist.","He works in a shoe shop.","He is an animator."],"a":1,"e":"“Duc works in a shoe shop” (hiện làm ở cửa hàng giày).","ev":"Duc works in a shoe shop"},{"k":"tf","q":"Duc's first model looked very good.","a":1,"e":"Mô hình đầu tiên “looked more like a strange rock” (trông như hòn đá kỳ quặc) → Sai.","ev":"looked more like a strange rock"},{"k":"mc","q":"How did Duc learn?","o":["He went to an expensive school.","He practised every night with free online lessons.","His friend taught him at work."],"a":1,"e":"“Every night he practised for one hour and followed free lessons online.”","ev":"Every night he practised for one hour and followed free lessons online."},{"k":"mc","q":"What did Duc make last month?","o":["A cup","A robot character","A shoe"],"a":1,"e":"“a small game character, a cute robot with big eyes”.","ev":"a cute robot with big eyes"},{"k":"tf","q":"Duc already works for the game company.","a":1,"e":"Tuần sau anh ấy mới có buổi phỏng vấn đầu tiên, chưa làm ở đó → Sai.","ev":"Next week, Duc has his first interview"}]},{"id":"b1-remote","lv":3,"icon":"🏠","t":"Working from Home","vi":"Làm việc tại nhà","topic":"Công việc","p":["Since 2020, millions of office workers around the world have tried working from home. For some, it has been a dream come true; for others, it has been more difficult than they expected.","The most obvious advantage is time. People who used to spend an hour or more in traffic can now use that time to sleep, exercise or be with their families. Many also say they can concentrate better without colleagues chatting next to them, and companies can save money on office space.","However, working from home also has disadvantages. Some people find it hard to separate work from private life, so they end up answering emails late at night. Others feel lonely because they miss the small conversations that happen in the office kitchen. Young employees, in particular, say it is harder to learn from experienced colleagues when everyone is behind a screen.","Because of this, many companies now choose a \"hybrid\" model: staff work in the office two or three days a week and at home on the other days. Experts believe this mix may offer the best of both worlds, but they agree on one thing: clear rules about working hours are essential."],"g":[["advantage","lợi thế, ưu điểm"],["concentrate","tập trung"],["colleague","đồng nghiệp"],["separate","tách biệt"],["private life","đời sống riêng"],["lonely","cô đơn"],["experienced","có kinh nghiệm"],["hybrid","kết hợp"],["essential","thiết yếu"]],"q":[{"k":"mc","q":"According to the text, what is the most obvious advantage of working from home?","o":["Higher salaries","Saving travel time","Better computers"],"a":1,"e":"“The most obvious advantage is time.” Người ta không phải mất thời gian kẹt xe.","ev":"The most obvious advantage is time."},{"k":"tfng","q":"Companies can save money on office space.","a":0,"e":"“companies can save money on office space” → Đúng (True).","ev":"companies can save money on office space"},{"k":"tfng","q":"Most workers earn more money when they work from home.","a":2,"e":"Bài không nói gì về thu nhập của người lao động → Không có thông tin (Not Given).","ev":""},{"k":"mc","q":"Why do young employees find working from home harder?","o":["They do not have good internet.","It is harder to learn from experienced colleagues.","They have to work more hours."],"a":1,"e":"“it is harder to learn from experienced colleagues when everyone is behind a screen”.","ev":"it is harder to learn from experienced colleagues when everyone is behind a screen"},{"k":"mc","q":"What do experts agree on?","o":["Everyone should return to the office.","Clear rules about working hours are essential.","Hybrid work does not work."],"a":1,"e":"“they agree on one thing: clear rules about working hours are essential.”","ev":"clear rules about working hours are essential"}]},{"id":"b1-plastic","lv":3,"icon":"♻️","t":"Living with Less Plastic","vi":"Sống ít nhựa hơn","topic":"Môi trường","p":["Every year, people produce more than 400 million tonnes of plastic, and a large part of it is used only once: a bag for ten minutes, a straw for one drink, a bottle for a few hours. Much of this waste ends up in rivers and oceans, where it can stay for hundreds of years.","Thao, a 28-year-old designer from Da Nang, decided to change her habits after a diving trip. \"I saw a turtle with a plastic bag around its neck,\" she says. \"I couldn't stop thinking about it.\"","She started with small steps. She bought a metal water bottle and a cloth shopping bag, and she began carrying a lunch box when she bought street food. At first, some sellers looked surprised, but now they recognise her and even give her a small discount.","The hardest part, she admits, is online shopping, because many products arrive wrapped in several layers of plastic. Now she chooses shops that use paper packaging whenever she can.","Thao knows that one person cannot solve the problem alone. \"But if I can change, my friends might change too,\" she says. Three of her colleagues have already followed her example."],"g":[["produce","sản xuất, thải ra"],["tonne","tấn"],["waste","rác thải"],["habit","thói quen"],["turtle","con rùa"],["recognise","nhận ra"],["discount","giảm giá"],["admit","thừa nhận"],["packaging","bao bì"]],"q":[{"k":"mc","q":"What made Thao change her habits?","o":["A TV programme","Something she saw while diving","Advice from her colleagues"],"a":1,"e":"Sau một chuyến lặn, cô thấy một con rùa bị túi nhựa quấn quanh cổ.","ev":"decided to change her habits after a diving trip"},{"k":"tfng","q":"Some street food sellers now give Thao a discount.","a":0,"e":"“now they recognise her and even give her a small discount” → True.","ev":"even give her a small discount"},{"k":"tfng","q":"Thao has stopped shopping online.","a":1,"e":"Cô vẫn mua online, chỉ chọn shop dùng bao bì giấy khi có thể → False.","ev":"Now she chooses shops that use paper packaging whenever she can."},{"k":"tfng","q":"Thao works for an environmental organisation.","a":2,"e":"Bài chỉ nói cô là nhà thiết kế, không nói làm cho tổ chức môi trường → Not Given.","ev":""},{"k":"mc","q":"What does Thao believe?","o":["One person can solve the problem.","Her change can influence other people.","Plastic is not a serious problem."],"a":1,"e":"“if I can change, my friends might change too” và đã có 3 đồng nghiệp làm theo.","ev":"But if I can change, my friends might change too"}]},{"id":"b1-sleep","lv":3,"icon":"😴","t":"Why We Need Sleep","vi":"Vì sao chúng ta cần ngủ","topic":"Sức khỏe","p":["Most adults need between seven and nine hours of sleep a night, yet many people regularly get less. Students stay up late to study, office workers answer messages in bed, and parents of young children rarely sleep through the night.","Scientists now know that sleep is not just \"switching off\". While we sleep, the brain organises the information we learned during the day and stores important memories. This is why students who sleep well after studying usually remember more than those who stay awake all night.","Sleep also affects our bodies. People who sleep too little have a higher risk of weight gain, heart problems and getting sick, because the body needs rest to repair itself. Even our mood suffers: after a bad night, small problems can feel much bigger.","Fortunately, a few simple habits can help. Experts recommend going to bed and getting up at the same time every day, even at weekends. They also suggest avoiding coffee in the afternoon and keeping phones out of the bedroom, since the light from screens tells the brain that it is still daytime."],"g":[["regularly","thường xuyên"],["stay up late","thức khuya"],["organise","sắp xếp"],["memory","trí nhớ, ký ức"],["risk","nguy cơ"],["weight gain","tăng cân"],["repair","sửa chữa, phục hồi"],["mood","tâm trạng"],["recommend","khuyên"]],"q":[{"k":"mc","q":"How much sleep do most adults need?","o":["Five to six hours","Seven to nine hours","Ten hours or more"],"a":1,"e":"“Most adults need between seven and nine hours of sleep a night”.","ev":"Most adults need between seven and nine hours of sleep a night"},{"k":"mc","q":"What does the brain do during sleep?","o":["It stops working completely.","It organises information and stores memories.","It creates new problems."],"a":1,"e":"“the brain organises the information we learned during the day and stores important memories”.","ev":"the brain organises the information we learned during the day and stores important memories"},{"k":"tfng","q":"Students who sleep after studying usually remember more.","a":0,"e":"Bài viết khẳng định điều này → True.","ev":"students who sleep well after studying usually remember more"},{"k":"tfng","q":"Sleeping more than nine hours is dangerous for adults.","a":2,"e":"Bài không nói về việc ngủ quá 9 tiếng → Not Given.","ev":""},{"k":"mc","q":"Why should we keep phones out of the bedroom?","o":["Phones are too noisy.","Screen light makes the brain think it is still daytime.","Phones use too much electricity at night."],"a":1,"e":"“the light from screens tells the brain that it is still daytime”.","ev":"the light from screens tells the brain that it is still daytime"}]},{"id":"b1-volunteer","lv":3,"icon":"🤝","t":"A Summer of Volunteering","vi":"Một mùa hè tình nguyện","topic":"Xã hội","p":["Last summer, instead of finding a part-time job, Bao spent six weeks as a volunteer teacher in a mountain village in Ha Giang. He had never taught before, and he was nervous about standing in front of a class of thirty children.","Life in the village was very different from his life in the city. There was no air conditioning, the internet worked only in the evening, and he had to walk forty minutes to the school on a muddy path. At first, he found it exhausting.","The children, however, changed his mind quickly. They were curious, cheerful and eager to learn. Most of them spoke H'Mong at home, so Bao used songs, games and pictures to teach basic English and maths. In return, they taught him words in their language and showed him how to catch fish in the stream.","On his last day, the class gave him a handmade bracelet and a drawing of him with a very big nose. Bao laughed, but he also cried a little. \"I went there to teach,\" he says, \"but I think I learned more than they did.\""],"g":[["volunteer","tình nguyện viên"],["nervous","lo lắng, hồi hộp"],["muddy","lầy lội"],["exhausting","mệt nhoài"],["curious","tò mò"],["eager","háo hức"],["in return","đáp lại"],["stream","con suối"],["bracelet","vòng tay"]],"q":[{"k":"tfng","q":"Bao had a lot of teaching experience before the trip.","a":1,"e":"“He had never taught before” → False.","ev":"He had never taught before"},{"k":"mc","q":"Which of these was NOT a difficulty in the village?","o":["No air conditioning","A long walk to school","Not enough food"],"a":2,"e":"Khó khăn: không điều hòa, mạng chỉ có buổi tối, đi bộ 40 phút. Bài không nhắc tới thiếu ăn.","ev":"There was no air conditioning"},{"k":"mc","q":"How did Bao teach the children?","o":["With songs, games and pictures","Only with textbooks","With videos on the internet"],"a":0,"e":"“Bao used songs, games and pictures to teach basic English and maths.”","ev":"Bao used songs, games and pictures to teach basic English and maths."},{"k":"tfng","q":"The children taught Bao how to catch fish.","a":0,"e":"“showed him how to catch fish in the stream” → True.","ev":"showed him how to catch fish in the stream"},{"k":"mc","q":"What does Bao mean by \"I learned more than they did\"?","o":["The children were bad students.","The experience taught him a lot.","He studied H'Mong at university."],"a":1,"e":"Anh muốn nói chính trải nghiệm này đã dạy anh rất nhiều, có lẽ còn nhiều hơn những gì anh dạy bọn trẻ.","ev":"I think I learned more than they did"}]},{"id":"b1-render","lv":3,"icon":"🎬","t":"How an Animated Film Is Made","vi":"Phim hoạt hình được làm ra sao","topic":"Công nghệ 3D","p":["When we watch a 3D animated film, we see only ninety minutes of colourful characters and exciting action. Behind those ninety minutes, however, there are usually three or four years of work by hundreds of artists and engineers.","Everything starts with a story. Writers and directors create a script, and story artists draw thousands of simple sketches, called storyboards, to plan every scene. Only when the story works on paper does the 3D work begin.","Next, modellers build the characters and the world in special software. Each character is given a digital skeleton, a process called rigging, so that animators can move it like a puppet. Animators then create the movements one pose at a time; a good animator may finish only four or five seconds of animation in a week.","Finally, lighting artists add light and shadow, and the computers start rendering, which means calculating the final images. A single frame can take several hours to render, and a film has more than 100,000 frames. That is why studios use huge \"render farms\" with thousands of computers working day and night."],"g":[["script","kịch bản"],["sketch","bản phác thảo"],["storyboard","kịch bản phân cảnh"],["modeller","người dựng mô hình"],["rigging","dựng xương điều khiển"],["puppet","con rối"],["pose","tư thế"],["render","kết xuất hình ảnh"],["frame","khung hình"]],"q":[{"k":"mc","q":"How long does it usually take to make a 3D animated film?","o":["About ninety days","Three or four years","Ten years"],"a":1,"e":"“there are usually three or four years of work”.","ev":"there are usually three or four years of work"},{"k":"mc","q":"What are storyboards?","o":["Simple drawings that plan each scene","The final images of the film","Digital skeletons for characters"],"a":0,"e":"Storyboards là hàng nghìn bản phác thảo đơn giản dùng để lên kế hoạch cho từng cảnh.","ev":"called storyboards, to plan every scene"},{"k":"tfng","q":"Rigging allows animators to move characters like puppets.","a":0,"e":"“so that animators can move it like a puppet” → True.","ev":"so that animators can move it like a puppet"},{"k":"tfng","q":"A good animator can finish one minute of animation in a day.","a":1,"e":"Một họa sĩ giỏi chỉ làm được 4–5 giây mỗi tuần, nên không thể có 1 phút mỗi ngày → False.","ev":"a good animator may finish only four or five seconds of animation in a week"},{"k":"mc","q":"Why do studios need render farms?","o":["Because rendering every frame takes a very long time","Because artists work from home","Because the software is free"],"a":0,"e":"Mỗi khung hình mất vài giờ và phim có hơn 100.000 khung hình, nên cần hàng nghìn máy tính cùng chạy.","ev":"A single frame can take several hours to render"}]},{"id":"b1-language","lv":3,"icon":"🗣️","t":"Learning a Language as an Adult","vi":"Học ngoại ngữ khi đã lớn","topic":"Giáo dục","p":["Many adults believe that it is too late for them to learn a new language. \"Children learn quickly,\" they say, \"but my brain is too old.\" Research suggests that this belief is only partly true.","It is true that young children usually develop a more natural accent, because they hear and copy sounds easily. However, adults have important advantages. They already understand how grammar works in their first language, they can use dictionaries and apps, and they can plan their own learning. In studies that compare the first year of learning, adults often make faster progress than children.","The biggest difference is usually not age but time and motivation. A child at an international school might hear English for six hours a day, while a busy adult may study for only two hours a week. Adults also worry more about making mistakes, so they speak less.","Teachers therefore give adult learners similar advice: study a little every day instead of a lot once a week, choose materials that are interesting to you, and accept that mistakes are a normal part of learning. As one teacher puts it, \"Your accent tells people where you come from. It doesn't stop them from understanding you.\""],"g":[["belief","niềm tin, quan niệm"],["partly","một phần"],["accent","giọng, trọng âm vùng miền"],["copy","bắt chước"],["progress","sự tiến bộ"],["motivation","động lực"],["materials","tài liệu"],["accept","chấp nhận"]],"q":[{"k":"mc","q":"According to research, the belief that adults cannot learn languages is…","o":["completely true","only partly true","completely false"],"a":1,"e":"“Research suggests that this belief is only partly true.”","ev":"Research suggests that this belief is only partly true."},{"k":"mc","q":"What advantage do children have?","o":["They plan their learning better.","They usually develop a more natural accent.","They understand grammar rules."],"a":1,"e":"“young children usually develop a more natural accent”.","ev":"young children usually develop a more natural accent"},{"k":"tfng","q":"In the first year, adults often learn faster than children.","a":0,"e":"“adults often make faster progress than children” → True.","ev":"adults often make faster progress than children"},{"k":"tfng","q":"Adults worry less about mistakes than children do.","a":1,"e":"“Adults also worry more about making mistakes” → lo nhiều hơn → False.","ev":"Adults also worry more about making mistakes"},{"k":"mc","q":"Which advice is given in the text?","o":["Study a lot once a week.","Study a little every day.","Only study grammar."],"a":1,"e":"“study a little every day instead of a lot once a week”.","ev":"study a little every day instead of a lot once a week"}]},{"id":"b2-ai","lv":4,"icon":"🤖","t":"Will AI Take Our Jobs?","vi":"AI có lấy mất việc của chúng ta?","topic":"Công nghệ","p":["Few questions cause as much anxiety today as this one: will artificial intelligence take our jobs? Headlines regularly predict that millions of positions will disappear, from translators and customer service agents to illustrators and programmers.","History offers a more complicated picture. When ATMs spread in the 1980s, many people expected bank tellers to vanish. Instead, banks opened more branches because each one became cheaper to run, and the number of tellers actually rose for several years. Their job, however, changed: they spent less time counting cash and more time advising customers.","Economists argue that AI is likely to follow a similar pattern, at least in the short term. Rather than replacing entire occupations, it tends to automate particular tasks within them. A designer might use AI to generate quick variations of an idea, but still decide which direction fits the client's brand. A doctor might rely on software to flag unusual results in a scan, while remaining responsible for the diagnosis.","That does not mean the transition will be painless. Workers whose tasks are easiest to automate, especially routine office work, may face real pressure, and not everyone will find it easy to retrain. Critics also point out that productivity gains do not automatically lead to higher wages; that depends on how companies and governments share the benefits.","What seems clear is that the skills most difficult to automate are distinctly human ones: judgement, creativity, empathy and the ability to work with others. Ironically, the more capable machines become, the more valuable these qualities may turn out to be."],"g":[["anxiety","sự lo âu"],["predict","dự đoán"],["bank teller","giao dịch viên ngân hàng"],["vanish","biến mất"],["automate","tự động hóa"],["occupation","nghề nghiệp"],["diagnosis","chẩn đoán"],["retrain","đào tạo lại"],["empathy","sự đồng cảm"],["ironically","trớ trêu thay"]],"q":[{"k":"mc","q":"What happened to bank tellers after ATMs became common?","o":["They disappeared quickly.","Their number rose for several years, but their job changed.","They earned much higher salaries."],"a":1,"e":"Số giao dịch viên còn tăng trong vài năm, nhưng công việc chuyển sang tư vấn khách hàng nhiều hơn.","ev":"the number of tellers actually rose for several years"},{"k":"mc","q":"According to economists, AI tends to…","o":["replace whole occupations","automate certain tasks within jobs","create no new tasks"],"a":1,"e":"“Rather than replacing entire occupations, it tends to automate particular tasks within them.”","ev":"it tends to automate particular tasks within them"},{"k":"tfng","q":"In the doctor example, the software makes the final diagnosis.","a":1,"e":"Bác sĩ vẫn “remaining responsible for the diagnosis” (chịu trách nhiệm chẩn đoán) → False.","ev":"while remaining responsible for the diagnosis"},{"k":"tfng","q":"Higher productivity always results in higher wages.","a":1,"e":"Các nhà phê bình nói năng suất tăng không tự động dẫn đến lương cao hơn → False.","ev":"productivity gains do not automatically lead to higher wages"},{"k":"mc","q":"What is the writer's conclusion?","o":["Machines will soon have empathy.","Human skills like judgement and creativity may become more valuable.","Routine office work is the most secure."],"a":1,"e":"Đoạn cuối: kỹ năng khó tự động hóa nhất là kỹ năng con người, và chúng có thể còn giá trị hơn nữa.","ev":"the more valuable these qualities may turn out to be"}]},{"id":"b2-city","lv":4,"icon":"🏙️","t":"Cities Built for People","vi":"Thành phố dành cho con người","topic":"Đô thị","p":["For most of the twentieth century, cities were designed around cars. Wide roads cut through old neighbourhoods, pavements shrank, and public squares turned into car parks. The logic seemed simple: more roads would mean less traffic.","In practice, the opposite often happened. Transport researchers describe a phenomenon called \"induced demand\": when a new road makes driving easier, more people choose to drive, and within a few years the road is just as congested as before. Several cities that built huge motorways in the 1970s found themselves with worse traffic, more pollution and fewer people walking in their streets.","Over the last two decades, a growing number of cities have tried a different approach. Paris has turned some riverside roads into parks and added hundreds of kilometres of cycle lanes. Seoul removed an elevated highway to restore the Cheonggyecheon stream, which now attracts millions of visitors a year. In each case, critics predicted traffic chaos; in each case, the chaos largely failed to appear, as some drivers switched to public transport or changed their routes.","Such projects are not without problems. Improving a neighbourhood can push up rents and force long-term residents to move away, a process known as gentrification. Shopkeepers sometimes fear that fewer cars will mean fewer customers, although studies frequently show that pedestrians and cyclists visit local shops more often.","The lesson, many planners argue, is that streets are not just pipes for moving vehicles. They are places where people meet, trade and live — and they should be designed that way."],"g":[["pavement","vỉa hè"],["shrink","thu hẹp"],["induced demand","nhu cầu kích thích"],["congested","tắc nghẽn"],["cycle lane","làn xe đạp"],["elevated highway","đường cao tốc trên cao"],["restore","khôi phục"],["chaos","sự hỗn loạn"],["gentrification","tái phát triển đô thị đẩy dân cũ đi"],["pedestrian","người đi bộ"]],"q":[{"k":"mc","q":"What does \"induced demand\" mean in the text?","o":["New roads attract more drivers, so traffic returns.","People demand more public transport.","Cities need more car parks."],"a":0,"e":"Đường mới làm lái xe dễ hơn → nhiều người lái xe hơn → vài năm sau lại tắc như cũ.","ev":"when a new road makes driving easier, more people choose to drive"},{"k":"mc","q":"What did Seoul do?","o":["Built a new motorway","Removed an elevated highway to restore a stream","Banned all cars from the centre"],"a":1,"e":"“Seoul removed an elevated highway to restore the Cheonggyecheon stream”.","ev":"Seoul removed an elevated highway to restore the Cheonggyecheon stream"},{"k":"tfng","q":"In Paris and Seoul, the predicted traffic chaos mostly did not happen.","a":0,"e":"“the chaos largely failed to appear” → True.","ev":"the chaos largely failed to appear"},{"k":"tfng","q":"Seoul's project was more expensive than the one in Paris.","a":2,"e":"Bài không so sánh chi phí → Not Given.","ev":""},{"k":"mc","q":"What do studies frequently show about shops?","o":["They lose customers when cars are reduced.","Pedestrians and cyclists visit local shops more often.","Shop owners prefer motorways."],"a":1,"e":"“studies frequently show that pedestrians and cyclists visit local shops more often”.","ev":"pedestrians and cyclists visit local shops more often"}]},{"id":"b2-gamedev","lv":4,"icon":"🎮","t":"The Hidden Cost of Beautiful Games","vi":"Cái giá ẩn sau những trò chơi đẹp","topic":"Công nghệ 3D","p":["Modern video games can look almost as realistic as films. Rain runs down windows, hair moves in the wind, and the sunlight changes as virtual hours pass. Behind this beauty lies a constant battle that players rarely notice: the fight for performance.","A film can spend hours rendering a single frame. A game, by contrast, must produce at least thirty — and ideally sixty or more — frames every second, on hardware the developers do not control. Every tree, character and reflection competes for a limited budget of processing power and memory.","To stay within that budget, technical artists rely on a toolbox of clever tricks. Distant objects are replaced by simpler versions with fewer polygons, a technique known as level of detail. Fine surface details, such as scratches on armour, are often painted into normal maps rather than modelled as real geometry. Lighting is frequently \"baked\" in advance, meaning it is calculated once and stored in textures instead of being computed live.","These decisions involve constant trade-offs. A more detailed character may look stunning in a trailer but cause the frame rate to drop during a busy battle, which players find far more irritating than slightly blurry textures. Teams therefore set strict limits: a main character might be allowed 60,000 triangles, while a background chair gets only a few hundred.","As hardware improves, these limits rise, but expectations rise with them. In that sense, optimisation is not a final step in game development; it is a discipline that shapes every choice from the very first sketch."],"g":[["realistic","chân thực"],["performance","hiệu năng"],["hardware","phần cứng"],["polygon","đa giác"],["level of detail","mức độ chi tiết (LOD)"],["normal map","normal map"],["bake","bake (tính trước, lưu vào texture)"],["trade-off","sự đánh đổi"],["frame rate","tốc độ khung hình"],["optimisation","tối ưu hóa"]],"q":[{"k":"mc","q":"What is the main difference between films and games mentioned in the text?","o":["Games must create many frames every second in real time.","Films use more characters.","Games do not use lighting."],"a":0,"e":"Phim có thể render hàng giờ cho một khung hình, còn game phải tạo ít nhất 30 khung hình mỗi giây.","ev":"must produce at least thirty — and ideally sixty or more — frames every second"},{"k":"mc","q":"What is \"level of detail\"?","o":["Painting scratches into textures","Using simpler versions of distant objects","Calculating lighting in advance"],"a":1,"e":"Vật ở xa được thay bằng phiên bản đơn giản hơn, ít đa giác hơn.","ev":"Distant objects are replaced by simpler versions with fewer polygons"},{"k":"tfng","q":"Baked lighting is calculated live while the game is running.","a":1,"e":"Baked lighting được tính trước một lần rồi lưu vào texture, không tính trực tiếp → False.","ev":"calculated once and stored in textures instead of being computed live"},{"k":"tfng","q":"Players usually prefer slightly blurry textures to a falling frame rate.","a":0,"e":"Người chơi thấy tụt khung hình khó chịu hơn nhiều so với texture hơi mờ → True.","ev":"which players find far more irritating than slightly blurry textures"},{"k":"mc","q":"According to the writer, optimisation is…","o":["the last step before release","a discipline that influences every decision","no longer needed with modern hardware"],"a":1,"e":"Tối ưu không phải bước cuối cùng mà là nguyên tắc định hình mọi lựa chọn từ bản phác thảo đầu tiên.","ev":"it is a discipline that shapes every choice from the very first sketch"}]},{"id":"b2-tourism","lv":4,"icon":"🧳","t":"When Tourists Become Too Many","vi":"Khi khách du lịch quá đông","topic":"Du lịch","p":["Tourism brings jobs, foreign currency and international attention, and for many developing regions it is one of the fastest routes out of poverty. Yet in some of the world's most famous destinations, residents have begun to protest against the very visitors their economies depend on.","The term \"overtourism\" describes the point at which the number of visitors damages the place they came to see. In Venice, cruise ships once delivered thousands of day-trippers at a time, crowding narrow streets while spending relatively little money. In parts of Barcelona, short-term rental apartments have replaced homes, pushing local families out of the centre.","Natural sites face similar pressure. Maya Bay in Thailand, made famous by a Hollywood film, received up to 5,000 visitors a day until authorities closed it in 2018 to allow the coral reef to recover. When it reopened, swimming was banned and daily numbers were strictly limited.","Governments are experimenting with a range of solutions: entry fees for day visitors, limits on rental licences, and campaigns that encourage travellers to explore less famous areas or visit outside peak season. Each measure has critics. Fees may turn heritage sites into places only the wealthy can enjoy, while promoting quieter regions risks simply moving the crowds elsewhere.","Ultimately, many experts argue, the question is not whether people should travel, but how. Staying longer in one place, using local businesses and respecting residents' daily lives can turn tourism back into something that benefits both visitors and hosts."],"g":[["foreign currency","ngoại tệ"],["poverty","nghèo đói"],["destination","điểm đến"],["protest","phản đối"],["day-tripper","khách du lịch trong ngày"],["short-term rental","cho thuê ngắn hạn"],["coral reef","rạn san hô"],["peak season","mùa cao điểm"],["heritage site","di sản"],["host","chủ nhà, nơi đón khách"]],"q":[{"k":"mc","q":"What is \"overtourism\"?","o":["When tourists spend too much money","When visitor numbers damage the place they visit","When a country has no tourists"],"a":1,"e":"“the point at which the number of visitors damages the place they came to see”.","ev":"the point at which the number of visitors damages the place they came to see"},{"k":"tfng","q":"Cruise ship passengers in Venice spent a lot of money in the city.","a":1,"e":"Họ “spending relatively little money” (tiêu tương đối ít) → False.","ev":"while spending relatively little money"},{"k":"mc","q":"Why was Maya Bay closed in 2018?","o":["To let the coral reef recover","Because of a storm","To build a hotel"],"a":0,"e":"Đóng cửa “to allow the coral reef to recover”.","ev":"to allow the coral reef to recover"},{"k":"tfng","q":"Maya Bay now allows swimming again.","a":1,"e":"Khi mở lại, “swimming was banned” → False.","ev":"swimming was banned"},{"k":"mc","q":"What is one criticism of entry fees?","o":["They are too cheap to work.","Only rich people may be able to visit.","They move crowds to other places."],"a":1,"e":"Phí vào cửa có thể biến di sản thành nơi chỉ người giàu được tận hưởng.","ev":"Fees may turn heritage sites into places only the wealthy can enjoy"}]},{"id":"b2-habits","lv":4,"icon":"🧠","t":"The Science of Habits","vi":"Khoa học về thói quen","topic":"Tâm lý","p":["Every January, millions of people promise themselves they will exercise more, eat better or spend less time on their phones. By February, most of those promises have been quietly abandoned. The problem, psychologists suggest, is not a lack of willpower but a misunderstanding of how habits work.","A habit is a behaviour that has become largely automatic. Researchers often describe it as a loop with three parts: a cue that triggers the behaviour, the routine itself, and a reward that makes the brain want to repeat it. Checking your phone when you feel bored is a classic example — boredom is the cue, scrolling is the routine, and the small hit of novelty is the reward.","Because habits are triggered by cues, one of the most effective strategies is to change your environment rather than rely on determination. People who keep fruit on the kitchen table eat more fruit; people who leave their running shoes by the door are more likely to go running. Making an unwanted habit slightly more inconvenient — logging out of social media apps, for instance — can be surprisingly powerful.","Another common mistake is starting too big. Instead of aiming for an hour at the gym, experts recommend a version so small it feels almost silly, such as two push-ups after brushing your teeth. Linking a new behaviour to an existing one in this way helps the brain build the connection.","Contrary to a popular myth, forming a habit does not take exactly twenty-one days. One frequently cited study found that it took participants anywhere from 18 to 254 days, with an average of around two months. Missing a single day, the same study found, made little difference in the long run."],"g":[["abandon","từ bỏ"],["willpower","ý chí"],["automatic","tự động"],["cue","tín hiệu kích hoạt"],["trigger","kích hoạt"],["reward","phần thưởng"],["novelty","sự mới lạ"],["inconvenient","bất tiện"],["myth","quan niệm sai lầm"],["participant","người tham gia"]],"q":[{"k":"mc","q":"According to psychologists, why do New Year promises often fail?","o":["People lack willpower.","People misunderstand how habits work.","People are too busy in February."],"a":1,"e":"“not a lack of willpower but a misunderstanding of how habits work”.","ev":"not a lack of willpower but a misunderstanding of how habits work"},{"k":"mc","q":"In the phone example, what is the cue?","o":["Scrolling","Boredom","Novelty"],"a":1,"e":"“boredom is the cue, scrolling is the routine”.","ev":"boredom is the cue"},{"k":"tfng","q":"Changing your environment can be more effective than relying on determination.","a":0,"e":"Một trong những chiến lược hiệu quả nhất là thay đổi môi trường → True.","ev":"one of the most effective strategies is to change your environment rather than rely on determination"},{"k":"tfng","q":"Most people need exactly twenty-one days to form a habit.","a":1,"e":"Đây là quan niệm sai: nghiên cứu cho thấy từ 18 đến 254 ngày, trung bình khoảng 2 tháng → False.","ev":"forming a habit does not take exactly twenty-one days"},{"k":"mc","q":"What did the study find about missing one day?","o":["It made little difference in the long run.","It meant starting again from zero.","It doubled the time needed."],"a":0,"e":"“Missing a single day … made little difference in the long run.”","ev":"made little difference in the long run"}]},{"id":"b2-coffee","lv":4,"icon":"☕","t":"Viet Nam's Coffee Story","vi":"Câu chuyện cà phê Việt Nam","topic":"Văn hóa","p":["Few visitors to Viet Nam leave without trying a glass of iced coffee with condensed milk. Yet many are surprised to learn that the country is the world's second-largest coffee producer, after Brazil, and the largest producer of robusta beans.","Coffee arrived with French missionaries in the nineteenth century, but production remained modest for a long time. The real boom came in the 1990s, when economic reforms allowed farmers in the Central Highlands to plant on a large scale. Within two decades, Viet Nam had transformed from a minor player into a global giant.","Robusta, the variety that dominates Vietnamese farms, is stronger and more bitter than arabica and contains almost twice as much caffeine. For years it was sold mainly to factories producing instant coffee, often at low prices. This explains, in part, the local habit of roasting beans dark and mixing them with sweet condensed milk.","Recently, however, the picture has been changing. A new generation of farmers and roasters is focusing on quality rather than quantity, carefully selecting ripe cherries and experimenting with processing methods. Specialty cafés in Ha Noi and Ho Chi Minh City now proudly serve \"fine robusta\", and some of these beans are winning international awards.","The industry still faces serious challenges, from falling groundwater levels to increasingly unpredictable weather. But for a crop that once seemed destined to remain cheap and anonymous, Vietnamese robusta has come a remarkably long way."],"g":[["condensed milk","sữa đặc"],["producer","nhà sản xuất"],["missionary","nhà truyền giáo"],["modest","khiêm tốn, nhỏ"],["boom","sự bùng nổ"],["reform","cải cách"],["variety","giống (cây)"],["bitter","đắng"],["ripe","chín"],["anonymous","vô danh"]],"q":[{"k":"mc","q":"Which country produces more coffee than Viet Nam?","o":["Colombia","Brazil","Ethiopia"],"a":1,"e":"Việt Nam là nước sản xuất cà phê lớn thứ hai “after Brazil”.","ev":"the world's second-largest coffee producer, after Brazil"},{"k":"mc","q":"When did coffee production really grow in Viet Nam?","o":["In the nineteenth century","In the 1990s","In the last two years"],"a":1,"e":"“The real boom came in the 1990s”.","ev":"The real boom came in the 1990s"},{"k":"tfng","q":"Robusta contains less caffeine than arabica.","a":1,"e":"Robusta có lượng caffeine gần gấp đôi arabica → False.","ev":"contains almost twice as much caffeine"},{"k":"tfng","q":"All Vietnamese coffee is now sold as \"fine robusta\".","a":1,"e":"Bài chỉ nói một thế hệ mới đang tập trung vào chất lượng và một số quán phục vụ “fine robusta”, không phải toàn bộ → False.","ev":"A new generation of farmers and roasters is focusing on quality rather than quantity"},{"k":"mc","q":"What challenge does the industry face?","o":["Too many tourists","Falling groundwater and unpredictable weather","A lack of cafés"],"a":1,"e":"“from falling groundwater levels to increasingly unpredictable weather”.","ev":"from falling groundwater levels to increasingly unpredictable weather"}]},{"id":"c1-attention","lv":5,"icon":"🎯","t":"The Attention Economy","vi":"Nền kinh tế của sự chú ý","topic":"Xã hội","p":["In the early days of the internet, commentators worried that information would become scarce or expensive. The opposite has happened. Information is now so abundant that the truly scarce resource is the attention required to process it — a shift the economist Herbert Simon anticipated as early as 1971, when he observed that \"a wealth of information creates a poverty of attention\".","Many of the platforms we use daily are free at the point of use because their real product is not the service itself but the time users spend on it, which is sold to advertisers. Under this model, success is measured in engagement: minutes watched, posts liked, notifications opened. Design choices follow accordingly. Infinite scrolling removes natural stopping points; autoplay begins the next video before the viewer has decided whether they want it; variable rewards, such as an unpredictable number of likes, exploit the same psychological mechanism that makes slot machines compelling.","Defenders of these platforms point out that they also provide genuine value — connecting distant relatives, giving small businesses access to customers, and enabling movements that traditional media ignored. They argue, moreover, that adults are capable of managing their own time, and that blaming technology risks treating users as passive victims.","Critics counter that the contest is hardly fair. On one side stands an individual with limited willpower at the end of a tiring day; on the other, teams of engineers armed with data on billions of interactions and a financial incentive to keep that individual scrolling. Framing the problem purely as one of personal discipline, they contend, conveniently shifts responsibility away from the companies that profit from it.","Proposed remedies range from the personal to the regulatory. Some people turn their screens to greyscale or delete apps altogether; some legislators have suggested banning certain design features for children or requiring platforms to offer feeds that are not ranked by engagement. Whatever one makes of these proposals, the debate itself reflects a growing recognition that attention, like any valuable resource, deserves to be protected rather than simply harvested."],"g":[["scarce","khan hiếm"],["abundant","dồi dào"],["anticipate","đoán trước"],["engagement","mức độ tương tác"],["exploit","khai thác, lợi dụng"],["compelling","cuốn hút khó cưỡng"],["passive","thụ động"],["incentive","động cơ, lợi ích thúc đẩy"],["remedy","biện pháp khắc phục"],["harvest","thu hoạch, khai thác"]],"q":[{"k":"mc","q":"What did Herbert Simon mean by \"a wealth of information creates a poverty of attention\"?","o":["Information has become too expensive.","When information is plentiful, attention becomes the scarce resource.","Rich people have less time to read."],"a":1,"e":"Khi thông tin dồi dào, thứ thực sự khan hiếm là sự chú ý cần để xử lý nó.","ev":"the truly scarce resource is the attention required to process it"},{"k":"mc","q":"According to the text, what is the \"real product\" of many free platforms?","o":["Their software","Users' time, sold to advertisers","Subscriptions"],"a":1,"e":"Sản phẩm thật là thời gian người dùng bỏ ra, được bán cho nhà quảng cáo.","ev":"the time users spend on it, which is sold to advertisers"},{"k":"tfng","q":"Variable rewards work in a similar way to slot machines.","a":0,"e":"Phần thưởng thất thường khai thác cùng cơ chế tâm lý khiến máy đánh bạc hấp dẫn → True.","ev":"exploit the same psychological mechanism that makes slot machines compelling"},{"k":"mc","q":"What is the critics' main objection to the \"personal discipline\" view?","o":["It ignores the unequal power between users and companies.","It is too expensive to implement.","Adults do not use social media."],"a":0,"e":"Cuộc chơi không công bằng: một cá nhân mệt mỏi đối đầu đội kỹ sư có dữ liệu và động cơ tài chính; đổ hết cho kỷ luật cá nhân là đẩy trách nhiệm khỏi các công ty.","ev":"conveniently shifts responsibility away from the companies that profit from it"},{"k":"tfng","q":"Some legislators have already banned infinite scrolling for all users.","a":2,"e":"Bài chỉ nói một số nhà lập pháp “đề xuất” cấm một số tính năng cho trẻ em, không nói đã cấm cho mọi người → Not Given.","ev":""}]},{"id":"c1-memory","lv":5,"icon":"🧩","t":"How Reliable Is Memory?","vi":"Trí nhớ đáng tin đến đâu?","topic":"Tâm lý","p":["We tend to think of memory as a kind of recording: an event happens, the brain stores it, and later we play it back. Decades of research suggest a rather different and more unsettling picture. Memories, it turns out, are reconstructed each time we recall them, and every act of remembering offers an opportunity for them to change.","Some of the most influential evidence comes from the psychologist Elizabeth Loftus. In a classic 1974 study, participants watched film of a car accident and were then asked how fast the cars were going when they \"hit\" or \"smashed into\" each other. Those who heard the word \"smashed\" not only gave higher speed estimates but, a week later, were more than twice as likely to report having seen broken glass — even though there was none in the film.","Later experiments went further, showing that entirely false memories can be implanted. With the help of family members, researchers persuaded a substantial minority of adult participants that they had been lost in a shopping centre as children. Many went on to describe the imaginary episode in vivid detail, complete with emotions and sensory impressions.","These findings have serious practical consequences, particularly in criminal justice. Eyewitness testimony is persuasive to juries, yet mistaken identification has been a factor in a large proportion of wrongful convictions later overturned by DNA evidence. In response, many police forces have revised their procedures, for example by ensuring that the officer conducting an identification line-up does not know which person is the suspect, so as not to give unintended cues.","None of this means that memory is generally useless. For most everyday purposes, it serves us well enough. But confidence, the research shows, is a poor guide to accuracy: a memory can feel vivid and certain and still be wrong. Recognising this may make us a little more humble when our recollections conflict with someone else's."],"g":[["reconstruct","tái dựng"],["unsettling","gây bất an"],["influential","có ảnh hưởng lớn"],["implant","cấy vào"],["substantial","đáng kể"],["vivid","sống động"],["testimony","lời khai"],["wrongful conviction","kết án oan"],["overturn","lật lại (phán quyết)"],["humble","khiêm tốn"]],"q":[{"k":"mc","q":"What is the main idea of the first paragraph?","o":["Memory works like a video recording.","Memories are rebuilt each time we recall them and can change.","Memory improves with age."],"a":1,"e":"Ký ức được tái dựng mỗi lần ta nhớ lại, và mỗi lần nhớ là một cơ hội để nó thay đổi.","ev":"Memories, it turns out, are reconstructed each time we recall them"},{"k":"tfng","q":"In Loftus's 1974 study, the film showed broken glass.","a":1,"e":"“even though there was none in the film” → không hề có kính vỡ → False.","ev":"even though there was none in the film"},{"k":"mc","q":"What effect did the word \"smashed\" have?","o":["Participants remembered the accident less clearly.","Participants estimated higher speeds and more often recalled broken glass.","Participants refused to answer."],"a":1,"e":"Nhóm nghe “smashed” ước lượng tốc độ cao hơn và hơn gấp đôi khả năng nói đã thấy kính vỡ.","ev":"not only gave higher speed estimates"},{"k":"tfng","q":"All participants in the shopping-centre study accepted the false memory.","a":1,"e":"Chỉ “a substantial minority” (một thiểu số đáng kể) bị thuyết phục → False.","ev":"persuaded a substantial minority of adult participants"},{"k":"mc","q":"Why should the officer running a line-up not know who the suspect is?","o":["To save time","To avoid giving the witness unintended cues","Because of DNA rules"],"a":1,"e":"Để không vô tình gợi ý cho nhân chứng.","ev":"so as not to give unintended cues"}]},{"id":"c1-digital-human","lv":5,"icon":"🧑‍🎨","t":"The Uncanny Valley","vi":"Thung lũng kỳ lạ","topic":"Công nghệ 3D","p":["In 1970, the Japanese roboticist Masahiro Mori proposed a deceptively simple idea. As robots become more human-like, he suggested, our sense of affinity towards them increases — but only up to a point. When a figure becomes almost, but not quite, human, that affinity suddenly collapses into unease or even revulsion, before recovering once the resemblance becomes perfect. Plotted on a graph, the dip resembles a valley, which Mori called bukimi no tani, now generally translated as the \"uncanny valley\".","For decades the concept attracted little attention outside robotics. It was the rise of computer-generated imagery that brought it into the mainstream. Several big-budget animated films of the early 2000s, which aimed for photorealistic human characters, were criticised by audiences and reviewers for faces that looked \"dead\" or \"waxy\", despite enormous technical achievement. By contrast, studios that deliberately stylised their characters — with oversized eyes, simplified skin and exaggerated proportions — rarely faced such complaints.","Researchers still debate why the effect occurs. One theory holds that near-human faces trigger an instinctive response associated with illness or death, since subtle abnormalities in skin tone or movement can signal disease. Another emphasises mismatch: we are disturbed when different cues contradict one another, for instance when a face has realistic skin but unnatural eye movements, or a human appearance combined with a synthetic voice.","For 3D artists, the practical lessons are instructive. Realism is not a single slider but a bundle of features that must be consistent with each other. A highly detailed face paired with stiff animation may be judged more harshly than a simpler design that moves convincingly. Small details carry disproportionate weight: the slight moisture along the lower eyelid, the way light scatters beneath the skin, or the tiny, irregular movements of the eyes known as saccades.","Advances in performance capture and real-time rendering have allowed some recent productions to climb out of the valley convincingly. Yet the concept remains a useful warning. Audiences, it seems, will happily accept a talking rabbit, but they are remarkably unforgiving of a human who is ninety-five per cent right."],"g":[["deceptively","tưởng chừng (nhưng không phải)"],["affinity","thiện cảm"],["revulsion","sự ghê sợ"],["resemblance","sự giống nhau"],["photorealistic","chân thực như ảnh chụp"],["stylise","cách điệu hóa"],["exaggerated","phóng đại"],["mismatch","sự không khớp"],["disproportionate","không tương xứng"],["subsurface scattering","tán xạ dưới bề mặt"]],"q":[{"k":"mc","q":"According to Mori, when does our affinity for a figure suddenly drop?","o":["When it looks clearly like a machine","When it is almost, but not quite, human","When it becomes perfectly human"],"a":1,"e":"Khi hình ảnh “almost, but not quite, human”, thiện cảm sụp đổ thành khó chịu.","ev":"When a figure becomes almost, but not quite, human"},{"k":"tfng","q":"The uncanny valley became widely known because of computer-generated imagery.","a":0,"e":"Chính sự phát triển của hình ảnh do máy tính tạo ra đã đưa khái niệm này vào dòng chính → True.","ev":"It was the rise of computer-generated imagery that brought it into the mainstream"},{"k":"mc","q":"Which theory explains the effect through contradiction between cues?","o":["The illness theory","The mismatch theory","The budget theory"],"a":1,"e":"Thuyết “mismatch”: ta bất an khi các tín hiệu mâu thuẫn nhau, ví dụ da thật nhưng mắt chuyển động không tự nhiên.","ev":"Another emphasises mismatch"},{"k":"mc","q":"What practical lesson does the writer give to 3D artists?","o":["Always aim for maximum detail.","All aspects of realism must be consistent with each other.","Avoid animating eyes."],"a":1,"e":"Độ chân thực là một tập hợp đặc điểm phải nhất quán với nhau.","ev":"Realism is not a single slider but a bundle of features that must be consistent with each other"},{"k":"tfng","q":"Stylised characters were frequently criticised for looking \"dead\".","a":1,"e":"Ngược lại, nhân vật cách điệu “rarely faced such complaints” → False.","ev":"rarely faced such complaints"}]},{"id":"c1-water","lv":5,"icon":"🌊","t":"The Sinking Delta","vi":"Đồng bằng đang lún","topic":"Môi trường","p":["The Mekong Delta, home to roughly seventeen million people, produces around half of Viet Nam's rice and a substantial share of its fruit and seafood. It is also, by many measures, one of the most vulnerable regions on Earth. While global attention tends to focus on rising sea levels, scientists increasingly argue that the delta faces a more immediate threat: the land itself is sinking.","Deltas are naturally dynamic landscapes. For thousands of years, the Mekong built its delta by depositing sediment carried from upstream, gradually raising the land and compensating for the natural compaction of soft soils. That balance has now been disrupted on several fronts. Dams built along the river and its tributaries trap a large proportion of the sediment before it reaches the sea, while extensive sand mining removes material directly from the riverbed.","At the same time, the extraction of groundwater for farming, industry and household use has accelerated subsidence. As water is pumped out of underground layers, the sediments compress, and the surface sinks — in some areas by more than two centimetres a year, several times faster than the current rate of sea-level rise. Because much of the delta lies barely a metre above sea level, the combined effect could be dramatic within decades.","The consequences are already visible. During recent dry seasons, saltwater has intruded tens of kilometres inland, damaging crops and forcing some farmers to switch from rice to shrimp or to abandon agriculture altogether. Riverbanks collapse more frequently, and coastal erosion has swallowed homes and mangrove forests.","Responses have shifted from an emphasis on controlling water towards what policymakers call \"living with nature\". Rather than building ever-higher dykes to keep saltwater out, some provinces now encourage farming systems adapted to brackish conditions, protect mangroves as natural barriers, and invest in alternative water supplies to reduce dependence on wells. Experts stress, however, that no local measure can fully succeed without cooperation among the countries upstream that share the river."],"g":[["vulnerable","dễ bị tổn thương"],["sediment","phù sa, trầm tích"],["compaction","sự nén chặt"],["tributary","phụ lưu"],["extraction","sự khai thác"],["subsidence","sự sụt lún"],["intrude","xâm nhập"],["erosion","xói mòn, sạt lở"],["brackish","nước lợ"],["mangrove","rừng ngập mặn"]],"q":[{"k":"mc","q":"According to scientists, what is a more immediate threat to the delta than rising seas?","o":["Tourism","The land sinking","Heavy rain"],"a":1,"e":"Mối đe dọa trước mắt hơn là bản thân đất đang lún.","ev":"the land itself is sinking"},{"k":"mc","q":"How did the Mekong naturally build its delta?","o":["By depositing sediment carried from upstream","Through volcanic activity","By human construction"],"a":0,"e":"Sông bồi phù sa mang từ thượng nguồn, nâng dần mặt đất.","ev":"depositing sediment carried from upstream"},{"k":"tfng","q":"In some areas, the land is sinking faster than the sea is rising.","a":0,"e":"Có nơi lún hơn 2 cm/năm, nhanh gấp nhiều lần tốc độ nước biển dâng → True.","ev":"several times faster than the current rate of sea-level rise"},{"k":"tfng","q":"The Vietnamese government has banned all groundwater extraction.","a":2,"e":"Bài chỉ nói đầu tư nguồn nước thay thế để giảm phụ thuộc giếng, không nói cấm hoàn toàn → Not Given.","ev":""},{"k":"mc","q":"What does \"living with nature\" involve?","o":["Building higher dykes everywhere","Adapting farming to salty water and protecting mangroves","Moving everyone out of the delta"],"a":1,"e":"Khuyến khích mô hình canh tác thích nghi với nước lợ, bảo vệ rừng ngập mặn, đầu tư nguồn nước thay thế.","ev":"encourage farming systems adapted to brackish conditions, protect mangroves as natural barriers"}]},{"id":"c1-translation","lv":5,"icon":"📚","t":"What Gets Lost in Translation","vi":"Điều gì mất đi khi dịch","topic":"Ngôn ngữ","p":["It is often said that translation is impossible, and yet it happens millions of times a day. Diplomats negotiate treaties across languages, readers in Ha Noi enjoy novels written in Spanish, and travellers point their phones at menus to see them rendered instantly into their mother tongue. The paradox dissolves once we recognise that translation is not the transfer of identical meaning from one container to another, but a series of informed compromises.","Some difficulties are lexical. Vietnamese distinguishes between anh, chị, em, cô, chú and many other forms of address that encode age, gender and social relationship; English typically collapses them all into \"you\". A translator rendering a family conversation must decide whether to lose this information, to signal it through other means, or to retain the original terms and trust the reader to adapt.","Other difficulties are structural. Vietnamese verbs do not change for tense, so a sentence may leave time implicit, relying on context or particles such as đã and sẽ. Translating into English forces a choice between past, present and future that the original may have left open. Conversely, English articles — \"a\" versus \"the\" — express distinctions that Vietnamese speakers usually convey, if at all, through word order or demonstratives.","The hardest challenges, however, tend to be cultural. Humour, wordplay and poetry depend on sound, rhythm and shared associations that rarely survive literal transfer. A pun that delights readers of the original may become a puzzling footnote. Translators of poetry must often choose between preserving form — rhyme, metre, the six-eight pattern of lục bát verse — and preserving sense, knowing that full fidelity to both is usually out of reach.","Machine translation has made remarkable progress, particularly for straightforward informational texts. Yet the decisions described above are not merely technical; they involve judgements about audience, purpose and tone. That is why, for the foreseeable future, the most reliable approach for important texts is likely to remain a collaboration: software for speed, and an experienced human for the choices that matter."],"g":[["paradox","nghịch lý"],["compromise","sự thỏa hiệp"],["lexical","thuộc từ vựng"],["form of address","cách xưng hô"],["retain","giữ lại"],["implicit","ngầm hiểu"],["particle","tiểu từ, hư từ"],["demonstrative","từ chỉ định"],["pun","cách chơi chữ"],["fidelity","sự trung thành (với bản gốc)"]],"q":[{"k":"mc","q":"How does the writer resolve the paradox that translation is \"impossible\" yet common?","o":["By saying machines solved it","By describing translation as a series of informed compromises","By saying only poetry is impossible"],"a":1,"e":"Nghịch lý được giải khi hiểu dịch là chuỗi thỏa hiệp có hiểu biết, không phải chuyển nghĩa y hệt.","ev":"but a series of informed compromises"},{"k":"mc","q":"What lexical problem is given as an example?","o":["Vietnamese forms of address versus English \"you\"","English spelling","Vietnamese tones"],"a":0,"e":"Tiếng Việt có anh, chị, em… mã hóa tuổi, giới tính, quan hệ; tiếng Anh gom lại thành “you”.","ev":"English typically collapses them all into \"you\""},{"k":"tfng","q":"Translating from Vietnamese into English can force a choice of tense that the original left open.","a":0,"e":"Động từ tiếng Việt không chia thì nên dịch sang tiếng Anh buộc phải chọn thì → True.","ev":"Translating into English forces a choice between past, present and future that the original may have left open"},{"k":"tfng","q":"Translators of poetry can usually preserve both form and sense completely.","a":1,"e":"Trung thành hoàn toàn cả hai “is usually out of reach” → False.","ev":"full fidelity to both is usually out of reach"},{"k":"mc","q":"What does the writer recommend for important texts?","o":["Using only machine translation","Combining software with an experienced human translator","Avoiding translation"],"a":1,"e":"Cách đáng tin nhất: phần mềm cho tốc độ, người có kinh nghiệm cho các lựa chọn quan trọng.","ev":"software for speed, and an experienced human for the choices that matter"}]},{"id":"c1-failure","lv":5,"icon":"🚀","t":"The Value of Failure","vi":"Giá trị của thất bại","topic":"Công việc","p":["\"Fail fast\" has become one of the most repeated slogans in the technology industry. Founders boast about their failed start-ups, and conferences invite speakers to describe their worst mistakes. To an older generation of managers, for whom failure was something to be hidden, this enthusiasm can seem bewildering.","There is a sound logic behind the slogan. In conditions of genuine uncertainty — launching a new product, say, or exploring an untested market — no amount of planning can reveal in advance what customers will actually want. Building a cheap prototype, testing it quickly and abandoning ideas that do not work is often far less costly than spending years perfecting something nobody needs. Seen this way, an early failure is not waste but information.","Research on organisations supports a related point. The Harvard professor Amy Edmondson, studying hospital teams, initially expected that the best-performing units would report the fewest errors. She found the opposite: stronger teams reported more. On closer examination, they were not making more mistakes; they simply felt safe enough to admit them, which allowed problems to be caught and corrected. Edmondson called this condition \"psychological safety\".","Yet the celebration of failure has its critics. Not all failures are equally instructive. A failed experiment that was well designed teaches something; a failure caused by carelessness or by ignoring obvious warnings teaches mainly that care was lacking. In fields such as aviation, surgery or bridge engineering, \"failing fast\" is obviously not a virtue. Moreover, the freedom to fail is unevenly distributed: an entrepreneur with family wealth can afford several collapses, while someone with debts and dependants may not survive one.","The more defensible position, perhaps, is neither to glorify failure nor to fear it, but to distinguish between its kinds. Organisations can encourage intelligent risks in areas where the cost of error is low, insist on rigorous procedures where it is high, and above all create cultures in which people report problems early rather than concealing them until they become disasters."],"g":[["slogan","khẩu hiệu"],["boast","khoe khoang"],["bewildering","khó hiểu, bối rối"],["uncertainty","sự bất định"],["prototype","nguyên mẫu"],["psychological safety","an toàn tâm lý"],["instructive","mang tính bài học"],["dependant","người phụ thuộc (con cái, người già)"],["defensible","có thể bảo vệ được"],["conceal","che giấu"]],"q":[{"k":"mc","q":"Why can \"failing fast\" make sense in uncertain situations?","o":["Because planning is always useless","Because quick, cheap tests reveal what customers want","Because investors prefer failure"],"a":1,"e":"Trong điều kiện bất định, thử nghiệm rẻ và nhanh cho thông tin mà lập kế hoạch không thể có.","ev":"an early failure is not waste but information"},{"k":"mc","q":"What did Edmondson discover about the best hospital teams?","o":["They made the fewest mistakes.","They reported more errors because they felt safe to admit them.","They had the most experienced doctors."],"a":1,"e":"Nhóm tốt báo cáo nhiều lỗi hơn vì họ cảm thấy đủ an toàn để thừa nhận.","ev":"they simply felt safe enough to admit them"},{"k":"tfng","q":"Edmondson expected the best teams to report the most errors.","a":1,"e":"Ban đầu bà nghĩ nhóm tốt nhất sẽ báo cáo ít lỗi nhất → False.","ev":"initially expected that the best-performing units would report the fewest errors"},{"k":"tfng","q":"According to the text, everyone has an equal ability to take the risk of failing.","a":1,"e":"Quyền được thất bại “is unevenly distributed” (phân bố không đều) → False.","ev":"the freedom to fail is unevenly distributed"},{"k":"mc","q":"What position does the writer finally support?","o":["Always celebrate failure.","Avoid all risks.","Distinguish between types of failure and respond accordingly."],"a":2,"e":"Không tôn vinh cũng không sợ thất bại, mà phân biệt các loại thất bại.","ev":"but to distinguish between its kinds"}]}];
/* ============================================================
   ĐỌC HIỂU A1–C1 (v145) — 30 bài tự soạn, mỗi cấp 6 bài, 5 câu hỏi / bài
   Chạm từ để tra nghĩa (từ điển trong app), nghe cả bài, dịch từng đoạn (cần mạng),
   đo tốc độ đọc, câu hỏi có giải thích + chỉ ra câu chứa đáp án trong bài.
============================================================ */
(function () {
  const root = document.getElementById('rd-root');
  if (!root || typeof RD_LESSONS === 'undefined') return;
  const E = (tag, cls, text) => { const e = document.createElement(tag); if (cls) e.className = cls; if (text != null) e.textContent = text; return e; };
  const KEY = 'hoc-tieng-anh-read', LVK = 'hoc-tieng-anh-read-lv', FSK = 'hoc-tieng-anh-read-fs';
  const LV = ['A1', 'A2', 'B1', 'B2', 'C1'], WPM = [60, 80, 100, 130, 160];
  let prog = {}; try { prog = JSON.parse(localStorage.getItem(KEY) || '{}') || {}; } catch (e) {}
  const save = () => { try { localStorage.setItem(KEY, JSON.stringify(prog)); } catch (e) {} };
  const st = { lv: 0, fs: 0 };
  try { const v = +localStorage.getItem(LVK); if (v >= 0 && v <= 5) st.lv = v; } catch (e) {}
  try { const v = +localStorage.getItem(FSK); if (v >= -1 && v <= 2) st.fs = v; } catch (e) {}
  const words = l => l.p.join(' ').split(/\s+/).filter(Boolean).length;
  const mins = l => Math.max(1, Math.round(words(l) / WPM[l.lv - 1]));
  const OPTS = { tf: ['True (Đúng)', 'False (Sai)'], tfng: ['True (Đúng)', 'False (Sai)', 'Not Given (Không có thông tin)'] };
  const opts = q => q.k === 'mc' ? q.o : OPTS[q.k];
  const top = () => { const m = document.querySelector('main'); window.scrollTo({ top: m ? Math.max(0, m.offsetTop - 8) : 0 }); };
  const say = (t, r) => { try { if (typeof speak === 'function') return speak(t, r || 0.9); } catch (e) {} return null; };
  let reading = null;   // phiên "nghe cả bài"
  const stopRead = () => { if (reading) { reading.stop = true; reading = null; } try { speechSynthesis.cancel(); } catch (e) {} };
  document.querySelectorAll('nav.tabbar button').forEach(b => b.addEventListener('click', () => { if (b.dataset.page !== 'page-read') { stopRead(); closePop(); } }));

  /* ---------- tra từ: thử dạng gốc (bỏ -s, -ed, -ing, quá khứ bất quy tắc) ---------- */
  let IRR_BACK = null;
  function lemmas(w) {
    w = w.toLowerCase().replace(/[’']s$/, '').replace(/[^a-z'-]/g, '');
    const out = [w];
    if (!IRR_BACK) { IRR_BACK = new Map(); try { IRREGULAR_VERBS.forEach(v => [v.v2, v.v3].forEach(f => String(f).split('/').forEach(x => { x = x.trim().toLowerCase(); if (x && !IRR_BACK.has(x)) IRR_BACK.set(x, v.v1); }))); } catch (e) {} }
    if (IRR_BACK.has(w)) out.push(IRR_BACK.get(w));
    if (/ies$/.test(w)) out.push(w.slice(0, -3) + 'y');
    if (/(s|x|z|ch|sh)es$/.test(w)) out.push(w.slice(0, -2));
    if (/s$/.test(w) && !/ss$/.test(w)) out.push(w.slice(0, -1));
    if (/ied$/.test(w)) out.push(w.slice(0, -3) + 'y');
    if (/ed$/.test(w)) { out.push(w.slice(0, -2), w.slice(0, -1)); if (/(.)\1ed$/.test(w)) out.push(w.slice(0, -3)); }
    if (/ing$/.test(w)) { out.push(w.slice(0, -3), w.slice(0, -3) + 'e'); if (/(.)\1ing$/.test(w)) out.push(w.slice(0, -4)); }
    if (/er$/.test(w)) out.push(w.slice(0, -2), w.slice(0, -1));
    if (/est$/.test(w)) out.push(w.slice(0, -3), w.slice(0, -2));
    if (/ly$/.test(w)) out.push(w.slice(0, -2), w.slice(0, -3) + 'le');
    return [...new Set(out)].filter(x => x.length > 0);
  }
  function lookup(w, l) {
    const lw = w.toLowerCase();
    const g = (l.g || []).find(x => x[0].toLowerCase() === lw || lemmas(w).includes(x[0].toLowerCase()));
    for (const k of lemmas(w)) {
      let r = {}; try { r = typeof prLookup === 'function' ? prLookup(k) : {}; } catch (e) {}
      if (r && (r.vi || r.ipa)) return { w: k, ipa: r.ipa, vi: g ? g[1] : r.vi, pos: r.pos };
    }
    return g ? { w: g[0], vi: g[1] } : { w: lw };
  }

  /* ---------- bảng tra từ ---------- */
  let pop = null;
  function closePop() { if (pop) { pop.remove(); pop = null; } document.querySelectorAll('.rd-w.on').forEach(x => x.classList.remove('on')); }
  function showPop(el, w, l) {
    closePop();
    el.classList.add('on');
    const r = lookup(w, l);
    pop = E('div', 'rd-pop'); pop.setAttribute('role', 'dialog'); pop.setAttribute('aria-label', 'Nghĩa của từ ' + r.w);
    const h = E('div', 'rd-pop-h');
    h.appendChild(E('b', null, r.w));
    if (r.ipa) h.appendChild(E('span', 'rd-pop-ipa', r.ipa));
    const x = E('button', 'rd-pop-x', '✕'); x.type = 'button'; x.setAttribute('aria-label', 'Đóng'); x.addEventListener('click', closePop); h.appendChild(x);
    pop.appendChild(h);
    const m = E('div', 'rd-pop-vi', r.vi || 'Chưa có trong từ điển offline.');
    pop.appendChild(m);
    // từ nằm trong một cụm ở "Từ cần biết" (vd. terraces → rice terraces): hiện nghĩa trong bài
    const lm = lemmas(w);
    const gph = (l.g || []).find(g => /\s/.test(g[0]) && g[0].toLowerCase().split(/\s+/).some(t => lm.includes(t) || lemmas(t).some(x => lm.includes(x))));
    if (gph) { const d = E('div', 'rd-pop-ctx'); d.appendChild(document.createTextNode('📌 Trong bài: ')); d.appendChild(E('b', null, gph[0])); d.appendChild(document.createTextNode(' = ' + gph[1])); pop.appendChild(d); }
    const act = E('div', 'rd-pop-act');
    const p1 = E('button', 'btn-ghost', '🔊 Nghe'); p1.type = 'button'; p1.addEventListener('click', () => say(r.w, 0.8)); act.appendChild(p1);
    if (!r.vi && typeof translateText === 'function') {
      const tr = E('button', 'btn-ghost', '🌐 Dịch'); tr.type = 'button';
      tr.addEventListener('click', async () => { tr.disabled = true; m.textContent = 'Đang dịch…'; try { const v = await translateText(r.w, 'en', 'vi'); m.textContent = (v && String(v.text || v).trim()) || 'Không dịch được.'; r.vi = m.textContent; } catch (e) { m.textContent = 'Không dịch được (cần mạng).'; } });
      act.appendChild(tr);
    }
    if (typeof window.srAddCard === 'function') {
      const ad = E('button', 'btn-ghost', '＋ Ôn tập'); ad.type = 'button';
      ad.addEventListener('click', () => { window.srAddCard(r.w, r.vi || ''); ad.textContent = '✓ Đã thêm'; ad.disabled = true; });
      act.appendChild(ad);
    }
    pop.appendChild(act);
    document.body.appendChild(pop);
    // đặt bảng ngay dưới (hoặc trên) từ được chạm
    const rc = el.getBoundingClientRect(), pw = Math.min(320, window.innerWidth - 24);
    pop.style.width = pw + 'px';
    let left = Math.min(Math.max(12, rc.left + rc.width / 2 - pw / 2), window.innerWidth - pw - 12);
    const below = rc.bottom + 8, ph = pop.offsetHeight;
    const topY = (below + ph > window.innerHeight - 70 && rc.top - ph - 8 > 8) ? rc.top - ph - 8 : below;
    pop.style.left = left + 'px'; pop.style.top = (topY + window.scrollY) + 'px';
    say(r.w, 0.8);
  }
  document.addEventListener('click', e => { if (pop && !pop.contains(e.target) && !e.target.closest('.rd-w')) closePop(); }, true);
  document.addEventListener('keydown', e => { if (e.key === 'Escape') closePop(); });

  /* ---------- danh sách bài ---------- */
  // v146: hai chế độ trong cùng tab: Đọc hiểu · Viết theo đề
  const MK2 = 'hoc-tieng-anh-rw-mode';
  let mode = 'read'; try { const m0 = localStorage.getItem(MK2); if (m0 === 'write' || m0 === 'listen') mode = m0; } catch (e) {}
  function modeBar() {
    const bar = E('div', 'rw-mode'); bar.setAttribute('role', 'tablist');
    [['read', '📖 Đọc'], ['listen', '🎧 Nghe'], ['write', '✍️ Viết']].forEach(([m, label]) => {
      const b = E('button', 'rw-tab' + (mode === m ? ' active' : ''), label); b.type = 'button'; b.setAttribute('role', 'tab'); b.setAttribute('aria-selected', String(mode === m));
      b.addEventListener('click', () => { if (mode === m) return; mode = m; try { localStorage.setItem(MK2, m); } catch (e) {} home(); });
      bar.appendChild(b);
    });
    return bar;
  }
  window.rdHome = m => { if (m) { mode = m; try { localStorage.setItem(MK2, m); } catch (e) {} } home(); };
  function home() {
    stopRead(); closePop();
    root.innerHTML = '';
    if (mode === 'write' && typeof window.wrHome === 'function') { window.wrHome(modeBar()); return; }
    if (mode === 'listen' && typeof window.lsHome === 'function') { window.lsHome(modeBar()); return; }
    root.appendChild(modeBar());
    const doneN = RD_LESSONS.filter(l => prog[l.id] && prog[l.id].best != null).length;
    const avgL = RD_LESSONS.map(l => prog[l.id] && prog[l.id].best).filter(x => x != null);
    const sum = E('div', 'tense-card rd-sum');
    sum.appendChild(E('div', 'rd-sum-t', `Đã đọc ${doneN}/${RD_LESSONS.length} bài` + (avgL.length ? ` · điểm trung bình ${Math.round(avgL.reduce((a, b) => a + b, 0) / avgL.length)}%` : '')));
    sum.appendChild(E('div', 'rv-note', 'Chạm vào từ bất kỳ để xem nghĩa. Mỗi bài có 5 câu hỏi; trả lời sai sẽ được ghi vào Sổ lỗi.'));
    root.appendChild(sum);
    const chips = E('div', 'colloc-chips rd-chips');
    [['Tất cả', 0], ...LV.map((x, i) => [x, i + 1])].forEach(([name, v]) => {
      const n = RD_LESSONS.filter(l => !v || l.lv === v), d = n.filter(l => prog[l.id] && prog[l.id].best != null).length;
      const b = E('button', 'colloc-chip' + (st.lv === v ? ' active' : ''), `${name} · ${d}/${n.length}`); b.type = 'button';
      b.addEventListener('click', () => { st.lv = v; try { localStorage.setItem(LVK, String(v)); } catch (e) {} home(); });
      chips.appendChild(b);
    });
    root.appendChild(chips);
    const list = RD_LESSONS.filter(l => !st.lv || l.lv === st.lv);
    const next = list.find(l => !(prog[l.id] && prog[l.id].best != null));
    const grid = E('div', 'rd-grid');
    list.forEach(l => {
      const p = prog[l.id], c = E('button', 'rd-card' + (p && p.best != null ? ' done' : '') + (l === next ? ' next' : '')); c.type = 'button';
      const h = E('div', 'rd-card-h'); h.appendChild(E('span', 'rd-ic', l.icon)); h.appendChild(E('span', 'rd-lv', LV[l.lv - 1]));
      if (p && p.best != null) h.appendChild(E('span', 'rd-st ' + (p.best >= 80 ? 'ok' : 'mid'), `✓ ${p.best}%`));
      else if (l === next) h.appendChild(E('span', 'rd-st nx', 'Gợi ý đọc tiếp'));
      c.appendChild(h);
      c.appendChild(E('div', 'rd-card-t', l.t));
      c.appendChild(E('div', 'rd-card-vi', l.vi));
      c.appendChild(E('div', 'rd-card-m', `${l.topic} · ${words(l)} từ · ~${mins(l)} phút`));
      c.addEventListener('click', () => lesson(l));
      grid.appendChild(c);
    });
    root.appendChild(grid);
  }

  /* ---------- một bài đọc ---------- */
  function lesson(l) {
    stopRead(); closePop();
    root.innerHTML = '';
    const P = prog[l.id] || {};
    const back = E('button', 'gr-back', '← Đọc hiểu'); back.type = 'button'; back.addEventListener('click', () => { home(); top(); });
    root.appendChild(back);
    const head = E('div', 'gr-head');
    head.appendChild(E('div', 'gr-en', `${LV[l.lv - 1]} · ${l.topic} · ${words(l)} từ · khoảng ${mins(l)} phút`));
    head.appendChild(E('h2', 'gr-title', l.icon + ' ' + l.t));
    head.appendChild(E('div', 'rd-vi-t', l.vi));
    root.appendChild(head);

    // thanh công cụ
    const bar = E('div', 'rd-bar');
    const play = E('button', 'btn-ghost rd-play', '▶ Nghe cả bài'); play.type = 'button';
    const slow = E('button', 'btn-ghost', '🐢 Chậm'); slow.type = 'button'; slow.setAttribute('aria-pressed', 'false');
    const fsm = E('button', 'btn-ghost rd-fs', 'A−'), fsp = E('button', 'btn-ghost rd-fs', 'A+'); fsm.type = fsp.type = 'button';
    fsm.setAttribute('aria-label', 'Chữ nhỏ hơn'); fsp.setAttribute('aria-label', 'Chữ to hơn');
    bar.appendChild(play); bar.appendChild(slow); bar.appendChild(fsm); bar.appendChild(fsp);
    root.appendChild(bar);
    root.appendChild(E('div', 'rd-tip', '💡 Chạm vào từ để xem nghĩa · 🌐 dưới mỗi đoạn để xem bản dịch'));

    // bài đọc: tách câu → từ
    const text = E('div', 'tense-card rd-text');
    const setFs = () => { text.style.fontSize = (17 + st.fs * 2) + 'px'; };
    setFs();
    fsm.addEventListener('click', () => { st.fs = Math.max(-1, st.fs - 1); try { localStorage.setItem(FSK, String(st.fs)); } catch (e) {} setFs(); });
    fsp.addEventListener('click', () => { st.fs = Math.min(2, st.fs + 1); try { localStorage.setItem(FSK, String(st.fs)); } catch (e) {} setFs(); });
    const sents = [];
    l.p.forEach(par => {
      const pe = E('p', 'rd-p');
      const lines = par.split('\n');
      lines.forEach((line, li) => {
        if (li) pe.appendChild(document.createElement('br'));
        (line.match(/[^.!?]+(?:[.!?]+["”’)]*|$)\s*/g) || [line]).forEach(sx => {
          if (!sx.trim()) return;
          const se = E('span', 'rd-s'); se.dataset.t = sx.trim();
          sx.split(/(\s+)/).forEach(tok => {
            if (!tok) return;
            if (/^\s+$/.test(tok)) { se.appendChild(document.createTextNode(tok)); return; }
            const m = /^([^A-Za-z]*)([A-Za-z][A-Za-z'’-]*[A-Za-z]|[A-Za-z])([^A-Za-z]*)$/.exec(tok);
            if (!m) { se.appendChild(document.createTextNode(tok)); return; }
            if (m[1]) se.appendChild(document.createTextNode(m[1]));
            const w = E('span', 'rd-w', m[2]); w.tabIndex = 0; w.setAttribute('role', 'button');
            w.addEventListener('click', e => { e.stopPropagation(); showPop(w, m[2].replace(/’/g, "'"), l); });
            w.addEventListener('keydown', e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); showPop(w, m[2].replace(/’/g, "'"), l); } });
            se.appendChild(w);
            if (m[3]) se.appendChild(document.createTextNode(m[3]));
          });
          pe.appendChild(se); sents.push(se);
        });
      });
      text.appendChild(pe);
      if (par.split(/\s+/).length > 4 && typeof translateText === 'function') {
        const tb = E('button', 'rd-tr', '🌐 Dịch đoạn này'); tb.type = 'button';
        const out = E('div', 'rd-tr-out'); out.hidden = true;
        tb.addEventListener('click', async () => {
          if (!out.hidden && out.dataset.ok) { out.hidden = true; tb.textContent = '🌐 Dịch đoạn này'; return; }
          out.hidden = false; tb.textContent = '🌐 Ẩn bản dịch';
          if (out.dataset.ok) return;
          out.textContent = 'Đang dịch…';
          try { const v = await translateText(par.replace(/\n/g, ' '), 'en', 'vi'); const s2 = (v && String(v.text || v).trim()) || ''; out.textContent = s2 || 'Không dịch được.'; if (s2) out.dataset.ok = '1'; }
          catch (e) { out.textContent = 'Không dịch được. Phần dịch cần kết nối mạng.'; }
        });
        text.appendChild(tb); text.appendChild(out);
      }
    });
    root.appendChild(text);

    // nghe cả bài, tô câu đang đọc
    let rate = 0.9;
    slow.addEventListener('click', () => { rate = rate === 0.9 ? 0.65 : 0.9; slow.classList.toggle('active', rate !== 0.9); slow.setAttribute('aria-pressed', String(rate !== 0.9)); });
    const mark = i => sents.forEach((s, k) => s.classList.toggle('reading', k === i));
    play.addEventListener('click', () => {
      if (reading) { stopRead(); mark(-1); play.textContent = '▶ Nghe cả bài'; return; }
      const R = reading = { stop: false };
      play.textContent = '⏹ Dừng';
      let i = 0;
      const nextS = () => {
        if (R.stop || i >= sents.length) { mark(-1); if (reading === R) { reading = null; play.textContent = '▶ Nghe cả bài'; } return; }
        mark(i);
        try { sents[i].scrollIntoView({ block: 'nearest', behavior: 'smooth' }); } catch (e) {}
        const u = say(sents[i].dataset.t, rate); i++;
        let gone = false; const go = () => { if (gone) return; gone = true; setTimeout(nextS, 120); };
        if (u && u.addEventListener) { u.addEventListener('end', go); u.addEventListener('error', e => { if (e && (e.error === 'interrupted' || e.error === 'canceled')) { R.stop = true; } go(); }); setTimeout(() => { if (!gone && !speechSynthesis.speaking && !speechSynthesis.pending) go(); }, 15000); }
        else go();
      };
      nextS();
    });

    // từ cần biết
    if (l.g && l.g.length) {
      const gb = E('div', 'tense-card rd-gloss');
      gb.appendChild(E('h3', null, '🔑 Từ cần biết'));
      const ul = E('div', 'rd-gl');
      l.g.forEach(([w, vi]) => { const b = E('button', 'rd-gli'); b.type = 'button'; b.appendChild(E('b', null, w)); b.appendChild(E('span', null, vi)); b.addEventListener('click', () => say(w, 0.8)); ul.appendChild(b); });
      gb.appendChild(ul);
      root.appendChild(gb);
    }

    // tốc độ đọc
    const t0 = Date.now();
    const sp = E('div', 'tense-card rd-speed');
    const fin = E('button', 'btn-primary', '⏱ Tôi đọc xong'); fin.type = 'button';
    const sres = E('div', 'rv-note', `Đọc hết bài rồi bấm nút để biết tốc độ đọc. Mức gợi ý cho ${LV[l.lv - 1]}: khoảng ${WPM[l.lv - 1]} từ/phút.`);
    fin.addEventListener('click', () => {
      const sec = Math.max(5, Math.round((Date.now() - t0) / 1000)), wpm = Math.round(words(l) / sec * 60);
      fin.hidden = true;
      const ok = wpm >= WPM[l.lv - 1] * 0.8;
      sres.textContent = `Bạn đọc ${words(l)} từ trong ${sec >= 60 ? Math.floor(sec / 60) + ' phút ' : ''}${sec % 60} giây ≈ ${wpm} từ/phút. ` + (wpm > WPM[l.lv - 1] * 2.5 ? 'Nhanh quá, bạn đã đọc kỹ chưa? Thử trả lời câu hỏi nhé.' : ok ? 'Tốc độ tốt cho cấp này 👍' : 'Hơi chậm so với mức gợi ý. Đọc lại vài lần sẽ nhanh dần.');
      const p2 = prog[l.id] || (prog[l.id] = {}); p2.wpm = wpm; save();
      try { qs.scrollIntoView({ behavior: 'smooth', block: 'start' }); } catch (e) {}
    });
    sp.appendChild(fin); sp.appendChild(sres);
    if (P.wpm) sp.appendChild(E('div', 'rv-note', `Lần trước: ${P.wpm} từ/phút.`));
    root.appendChild(sp);

    // câu hỏi
    const qs = E('div', 'rd-qs');
    qs.appendChild(E('h3', 'rd-qs-h', '❓ Câu hỏi'));
    if (l.lv >= 3) qs.appendChild(E('div', 'rv-note', 'Not Given = bài đọc không nhắc tới thông tin này (khác với False = bài nói ngược lại).'));
    const ans = {};
    const hl = q => {
      sents.forEach(s => s.classList.remove('ev'));
      if (!q.ev) return null;
      const hits = sents.filter(s => s.dataset.t.includes(q.ev) || q.ev.includes(s.dataset.t.replace(/["”’)]+$/, '')) || (q.ev.length > 12 && s.dataset.t.includes(q.ev.slice(0, 40))));
      hits.forEach(s => s.classList.add('ev'));
      return hits[0] || null;
    };
    l.q.forEach((q, qi) => {
      const c = E('div', 'tense-card rd-q');
      const qh = E('div', 'rd-q-h'); qh.appendChild(E('span', 'rd-q-n', String(qi + 1))); qh.appendChild(E('span', 'rd-q-t', q.q)); c.appendChild(qh);
      const os = E('div', 'rd-opts');
      const fb = E('div', 'gx-fb'); fb.hidden = true;
      opts(q).forEach((o, oi) => {
        const b = E('button', 'gx-opt', (q.k === 'mc' ? 'ABCD'[oi] + '. ' : '') + o); b.type = 'button';
        b.addEventListener('click', () => {
          if (ans[qi] != null) return;
          ans[qi] = oi;
          const ok = oi === q.a;
          os.querySelectorAll('.gx-opt').forEach((x, j) => { x.disabled = true; if (j === q.a) x.classList.add('ok'); else if (j === oi) x.classList.add('bad'); });
          fb.hidden = false; fb.className = 'gx-fb ' + (ok ? 'ok' : 'bad'); fb.innerHTML = '';
          fb.appendChild(E('div', 'gx-fb-t', ok ? '✓ Chính xác!' : '✗ Chưa đúng'));
          fb.appendChild(E('div', 'gx-why ' + (ok ? 'ok' : 'bad'), q.e));
          if (q.ev) {
            const sh = E('button', 'btn-ghost rd-show', '🔎 Xem câu trong bài'); sh.type = 'button';
            sh.addEventListener('click', () => { const s = hl(q); if (s) { try { s.scrollIntoView({ behavior: 'smooth', block: 'center' }); } catch (e) {} } });
            fb.appendChild(sh);
          }
          try { if (window.actLog) actLog('r'); } catch (e) {}
          try {
            const mk = 'rd|' + l.id + '|' + qi;
            if (ok) { if (window.mkOk) window.mkOk(mk); }
            else if (window.mkAdd) window.mkAdd({ k: mk, src: 'rd', cat: LV[l.lv - 1] + ' · ' + l.t, mode: 'mc', p: q.q, opts: opts(q), a: [opts(q)[q.a]], right: opts(q)[q.a], wrong: o, hint: q.ev ? '“' + q.ev + '”' : '', why: q.e });
          } catch (e) {}
          if (Object.keys(ans).length === l.q.length) finish();
        });
        os.appendChild(b);
      });
      c.appendChild(os); c.appendChild(fb);
      qs.appendChild(c);
    });
    root.appendChild(qs);
    const res = E('div', 'rd-res');
    root.appendChild(res);
    function finish() {
      const n = l.q.filter((q, i) => ans[i] === q.a).length, pct = Math.round(n / l.q.length * 100);
      const p2 = prog[l.id] || (prog[l.id] = {});
      const first = p2.best == null;
      p2.last = pct; p2.best = Math.max(p2.best || 0, pct); p2.n = (p2.n || 0) + 1; p2.t = Date.now(); save();
      res.innerHTML = '';
      const c = E('div', 'tense-card gx-score ' + (pct >= 80 ? 'ok' : pct >= 60 ? 'mid' : 'bad'));
      c.appendChild(E('div', 'gx-score-t', 'Kết quả'));
      c.appendChild(E('div', 'gx-score-big', `${n}/${l.q.length}`));
      c.appendChild(E('div', 'gx-score-sub', `${pct}% · tốt nhất ${p2.best}%` + (first ? ' · lần đầu' : '')));
      c.appendChild(E('div', 'gx-score-msg', pct === 100 ? 'Xuất sắc! Bạn hiểu bài rất tốt.' : pct >= 80 ? 'Rất tốt! Xem lại giải thích của câu sai nhé.' : pct >= 60 ? 'Khá ổn. Đọc lại bài, chú ý các câu được tô vàng khi bấm “Xem câu trong bài”.' : 'Bài này hơi khó. Hãy tra các từ mới rồi đọc lại một lần nữa.'));
      const row = E('div', 'rd-res-act');
      const again = E('button', 'btn-ghost', '↻ Làm lại'); again.type = 'button'; again.addEventListener('click', () => { lesson(l); top(); });
      row.appendChild(again);
      const list = RD_LESSONS.filter(x => x.lv === l.lv), i = list.indexOf(l);
      const nx = list[i + 1] || RD_LESSONS[RD_LESSONS.indexOf(l) + 1];
      if (nx) { const b = E('button', 'btn-primary', 'Bài tiếp: ' + nx.t + ' →'); b.type = 'button'; b.addEventListener('click', () => { lesson(nx); top(); }); row.appendChild(b); }
      c.appendChild(row);
      res.appendChild(c);
      try { c.scrollIntoView({ behavior: 'smooth', block: 'center' }); } catch (e) {}
    }
  }
  window.rdOpen = id => { const l = RD_LESSONS.find(x => x.id === id); if (l) lesson(l); else home(); };
  setTimeout(home, 0);   // chờ phần Viết (bên dưới) khai báo xong
})();
