const WR_TASKS = [{"id":"w-a1-me","lv":1,"icon":"🙋","type":"Giới thiệu","t":"Introduce yourself","vi":"Giới thiệu bản thân","task":"Write about yourself: your name, age, where you live, your job or school, your family and what you like.","taskVi":"Viết về bản thân: tên, tuổi, nơi sống, công việc hoặc trường học, gia đình và sở thích.","min":40,"max":70,"outline":["Câu 1–2: tên, tuổi, nơi sống","Câu 3–4: công việc / trường học","Câu 5–6: gia đình","Câu 7–8: sở thích, điều bạn thích làm cuối tuần"],"phrases":[["My name is …","Tên tôi là …"],["I am … years old.","Tôi … tuổi."],["I live in …","Tôi sống ở …"],["I work as a / an …","Tôi làm nghề …"],["There are … people in my family.","Nhà tôi có … người."],["In my free time, I like …","Lúc rảnh tôi thích …"]],"sample":"My name is Hieu and I am twenty-eight years old. I live in Ho Chi Minh City. I work as a 3D artist for a small game company. There are four people in my family: my parents, my sister and me. My sister is a nurse. In my free time, I like playing badminton and watching films. At the weekend, I often visit my parents."},{"id":"w-a1-day","lv":1,"icon":"⏰","type":"Miêu tả","t":"My daily routine","vi":"Một ngày của tôi","task":"Describe a normal day in your life. What do you do in the morning, afternoon and evening?","taskVi":"Miêu tả một ngày bình thường của bạn: buổi sáng, buổi chiều và buổi tối bạn làm gì.","min":40,"max":70,"outline":["Buổi sáng: giờ thức dậy, ăn sáng, đi làm / đi học","Buổi chiều: làm gì, ăn trưa ở đâu","Buổi tối: nấu ăn, giải trí, giờ đi ngủ"],"phrases":[["I usually get up at …","Tôi thường dậy lúc …"],["After breakfast, I …","Sau bữa sáng, tôi …"],["I go to work by …","Tôi đi làm bằng …"],["In the afternoon, …","Buổi chiều, …"],["I go to bed at about …","Tôi đi ngủ khoảng …"]],"sample":"I usually get up at half past six. I have bread and coffee for breakfast. Then I go to work by motorbike. I start work at eight. At noon, I have lunch with my colleagues near the office. In the afternoon, I work on my computer. I get home at six. In the evening, I cook dinner, read a book or watch YouTube. I go to bed at about eleven."},{"id":"w-a1-friend","lv":1,"icon":"👫","type":"Miêu tả","t":"My best friend","vi":"Người bạn thân nhất","task":"Write about your best friend. What is his or her name? What does he or she look like? What do you do together?","taskVi":"Viết về người bạn thân nhất: tên, ngoại hình, tính cách và hai bạn thường làm gì cùng nhau.","min":40,"max":70,"outline":["Tên, tuổi, quen nhau từ khi nào","Ngoại hình (cao/thấp, tóc, mắt…)","Tính cách (vui vẻ, tốt bụng…)","Hai bạn hay làm gì cùng nhau"],"phrases":[["My best friend is …","Bạn thân nhất của tôi là …"],["He / She is tall / short.","Bạn ấy cao / thấp."],["He / She has long / short hair.","Bạn ấy có tóc dài / ngắn."],["He / She is very kind / funny.","Bạn ấy rất tốt bụng / vui tính."],["We often … together.","Chúng tôi thường … cùng nhau."]],"sample":"My best friend is Lan. She is twenty-seven, the same age as me. We met at secondary school. Lan is not very tall and she has long black hair. She is kind and very funny. She works in a bank now. We often go to the cinema together on Friday evenings. Sometimes we cook dinner at her house. I am happy to have a friend like Lan."},{"id":"w-a1-note","lv":1,"icon":"📝","type":"Tin nhắn","t":"A short note","vi":"Viết lời nhắn ngắn","task":"You cannot meet your friend tomorrow. Write a short message. Say sorry, explain why, and suggest another day.","taskVi":"Ngày mai bạn không gặp bạn mình được. Viết tin nhắn ngắn: xin lỗi, nói lý do và hẹn một ngày khác.","min":30,"max":60,"outline":["Chào bạn","Xin lỗi, không gặp được ngày mai","Lý do (bận việc, ốm…)","Hẹn ngày khác + giờ","Lời chào cuối"],"phrases":[["Hi …,","Chào …,"],["I'm sorry, but I can't …","Xin lỗi, mình không thể …"],["because I have to …","vì mình phải …"],["Are you free on …?","Bạn có rảnh vào … không?"],["See you soon,","Hẹn gặp lại,"]],"sample":"Hi Nam,\nI'm sorry, but I can't meet you for coffee tomorrow. My boss wants me to finish a project, so I have to work late. Are you free on Saturday morning? We can meet at the same café at nine. Please let me know.\nSee you soon,\nHieu"},{"id":"w-a2-weekend","lv":2,"icon":"🌴","type":"Kể chuyện","t":"Last weekend","vi":"Cuối tuần vừa rồi","task":"Write about what you did last weekend. Where did you go? Who were you with? Did you enjoy it?","taskVi":"Kể về cuối tuần vừa rồi: bạn đi đâu, đi với ai, làm gì và có vui không. Dùng thì quá khứ đơn.","min":70,"max":110,"outline":["Mở: cuối tuần vừa rồi bạn đã làm gì nói chung","Thứ Bảy: đi đâu, với ai, làm gì","Chủ Nhật: làm gì","Kết: cảm nhận (vui, mệt, muốn làm lại…)"],"phrases":[["Last weekend, I …","Cuối tuần trước, tôi …"],["On Saturday morning, …","Sáng thứ Bảy, …"],["After that, we …","Sau đó, chúng tôi …"],["It was really …","Thật sự rất …"],["I had a great time.","Tôi đã rất vui."]],"sample":"Last weekend was very relaxing. On Saturday morning, I went to the countryside with my cousins to visit our grandparents. We helped my grandmother in her garden and picked some mangoes. In the afternoon, we swam in the river near her house. On Sunday, I stayed at home. I cleaned my room, did some shopping and watched two episodes of a Korean drama. In the evening, my friends came over and we cooked hotpot together. It was a simple weekend, but I had a great time and felt ready for the new week."},{"id":"w-a2-email","lv":2,"icon":"📧","type":"Email","t":"Invite a friend","vi":"Email mời bạn","task":"Write an email to an English-speaking friend. Invite him or her to your birthday party. Say when and where it is, what you will do, and what to bring.","taskVi":"Viết email mời một người bạn nói tiếng Anh đến tiệc sinh nhật: thời gian, địa điểm, sẽ làm gì và nên mang gì.","min":70,"max":110,"outline":["Chào + hỏi thăm","Lời mời: sinh nhật bạn, ngày giờ, địa điểm","Sẽ làm gì ở tiệc (ăn uống, karaoke…)","Nên mang gì / không cần mang gì","Đề nghị trả lời + lời chào"],"phrases":[["I hope you're well.","Mong bạn khỏe."],["I'm having a party for my birthday on …","Mình tổ chức tiệc sinh nhật vào …"],["It starts at … at …","Bắt đầu lúc … ở …"],["We're going to …","Chúng mình sẽ …"],["You don't need to bring anything.","Bạn không cần mang gì đâu."],["Let me know if you can come.","Cho mình biết bạn có đến được không nhé."]],"sample":"Hi Emma,\nI hope you're well and not too busy at work. I'm having a small party for my birthday on Saturday, 14th June, and I'd love you to come! It starts at seven in the evening at my flat in District 3. I'll send you the address later. We're going to have a barbecue on the roof, and after that we can sing karaoke in the living room. My sister is making a big chocolate cake. You don't need to bring a present, but if you want, you can bring some drinks. Let me know if you can come.\nBest wishes,\nHieu"},{"id":"w-a2-city","lv":2,"icon":"🏙️","type":"Miêu tả","t":"My hometown","vi":"Quê hương / thành phố của tôi","task":"Describe your hometown or city. Where is it? What is it famous for? What do you like and dislike about it?","taskVi":"Miêu tả quê hoặc thành phố của bạn: ở đâu, nổi tiếng về gì, bạn thích và không thích điều gì.","min":70,"max":120,"outline":["Tên, vị trí, quy mô","Nổi tiếng về gì (món ăn, cảnh đẹp, lễ hội…)","Điều bạn thích","Điều bạn không thích","Kết: bạn có muốn sống ở đó lâu dài không"],"phrases":[["… is in the north / centre / south of Viet Nam.","… nằm ở miền Bắc / Trung / Nam Việt Nam."],["It is famous for …","Nơi đó nổi tiếng về …"],["What I like most is …","Điều tôi thích nhất là …"],["However, …","Tuy nhiên, …"],["There is too much / There are too many …","Có quá nhiều …"]],"sample":"I come from Hoi An, a small city in the centre of Viet Nam. It is famous for its old town, with yellow houses, wooden shops and colourful lanterns. Many tourists visit every year, especially at the full moon festival, when people put candles on the river. What I like most is the food. Cao lau noodles and banh mi in Hoi An are the best in the country. The people are also friendly and the beach is only fifteen minutes away. However, the old town gets very crowded in summer, and sometimes there are floods in the rainy season. I live in Saigon now, but I want to go back to Hoi An when I am older."},{"id":"w-a2-review","lv":2,"icon":"⭐","type":"Đánh giá","t":"Review a restaurant","vi":"Đánh giá một quán ăn","task":"Write a short review of a restaurant or café you visited. Describe the place, the food, the service and the price. Would you recommend it?","taskVi":"Viết một bài đánh giá ngắn về quán ăn / quán cà phê bạn từng đến: không gian, món ăn, phục vụ, giá cả và có nên đến không.","min":70,"max":110,"outline":["Tên quán, ở đâu, bạn đến khi nào, với ai","Không gian","Món đã gọi + nhận xét","Phục vụ, giá cả","Kết luận + chấm điểm"],"phrases":[["Last week I tried …","Tuần trước tôi đã thử …"],["The place is small but cosy.","Quán nhỏ nhưng ấm cúng."],["I ordered …","Tôi đã gọi …"],["It was delicious / a bit too salty.","Món đó rất ngon / hơi mặn."],["The staff were friendly.","Nhân viên thân thiện."],["I would definitely recommend it.","Tôi chắc chắn sẽ giới thiệu quán này."]],"sample":"Last week I tried Mây, a new vegetarian café near my office. The place is small but cosy, with lots of plants and soft music. I went there for lunch with two colleagues. I ordered tofu with lemongrass and brown rice, and my friends had mushroom noodle soup. My dish was delicious and not too oily, but the soup was a bit too salty for my friends. The staff were friendly and the food came quickly. Lunch cost about 70,000 dong per person, which is reasonable. Overall, I would recommend Mây for a healthy lunch. I give it four stars out of five."},{"id":"w-b1-opinion","lv":3,"icon":"💭","type":"Nêu ý kiến","t":"Online or classroom learning?","vi":"Học online hay học trên lớp?","task":"Some people think online courses are better than classroom lessons. What is your opinion? Give reasons and examples.","taskVi":"Có người cho rằng học online tốt hơn học trên lớp. Ý kiến của bạn thế nào? Nêu lý do và ví dụ.","min":120,"max":180,"outline":["Mở bài: nêu vấn đề + quan điểm của bạn","Thân bài 1: lý do thứ nhất + ví dụ","Thân bài 2: lý do thứ hai + ví dụ (hoặc nhìn nhận mặt kia)","Kết bài: nhắc lại quan điểm"],"phrases":[["In my opinion, …","Theo ý kiến của tôi, …"],["First of all, …","Trước hết, …"],["For example, …","Ví dụ, …"],["On the other hand, …","Mặt khác, …"],["That is why …","Đó là lý do …"],["To sum up, …","Tóm lại, …"]],"sample":"Nowadays, more and more people take courses online instead of going to a classroom. In my opinion, online learning is very useful, but it cannot completely replace face-to-face lessons.\n\nFirst of all, online courses are flexible and often cheaper. For example, I learned 3D modelling from online videos after work, which would be impossible if I had to travel to a school every evening. I could also pause and watch difficult parts again.\n\nOn the other hand, classroom lessons have advantages that are hard to copy online. Students can ask questions immediately, work in groups and get feedback on their mistakes. In my English class, speaking with real classmates helped me feel more confident than practising alone at home. Many people also find it difficult to stay motivated without a teacher and a fixed timetable.\n\nTo sum up, I believe the best solution is to combine both: use online materials to study at your own speed, and join a class for speaking practice and support."},{"id":"w-b1-story","lv":3,"icon":"📖","type":"Kể chuyện","t":"A day that didn't go as planned","vi":"Một ngày không như kế hoạch","task":"Write a story that begins: \"It was supposed to be a perfect day, but…\". Describe what happened, how you felt and how it ended.","taskVi":"Viết một câu chuyện bắt đầu bằng câu: \"It was supposed to be a perfect day, but…\". Kể chuyện gì đã xảy ra, cảm xúc của bạn và kết thúc ra sao.","min":120,"max":180,"outline":["Mở: bối cảnh (ở đâu, với ai, kế hoạch là gì)","Diễn biến: sự cố xảy ra","Cao trào: bạn phản ứng thế nào, cảm xúc","Kết: mọi chuyện kết thúc ra sao, bài học"],"phrases":[["It was supposed to be a perfect day, but …","Đáng lẽ đó là một ngày hoàn hảo, nhưng …"],["Suddenly, …","Đột nhiên, …"],["I couldn't believe it.","Tôi không thể tin được."],["Luckily, …","May mắn thay, …"],["In the end, …","Cuối cùng, …"],["Looking back, …","Nhìn lại, …"]],"sample":"It was supposed to be a perfect day, but nothing went the way I had planned. My girlfriend and I were going to Vung Tau for her birthday. I had booked a hotel by the sea and a table at a nice seafood restaurant.\n\nWe left Saigon early on my motorbike. After about an hour, it suddenly started to rain heavily, and we had to stop under a bridge. Then, when the rain finally stopped, I realised that the back tyre was flat. I couldn't believe it. I felt embarrassed and angry with myself because I hadn't checked the bike before we left.\n\nLuckily, a kind old man nearby repaired the tyre for us and refused to take any money. He even gave us two cups of hot tea. We arrived in Vung Tau three hours late and missed our dinner reservation, so we ate grilled squid at a small street stall instead.\n\nIn the end, my girlfriend said it was her most memorable birthday. Looking back, I agree: the problems made the day special."},{"id":"w-b1-complaint","lv":3,"icon":"📦","type":"Email trang trọng","t":"A complaint email","vi":"Email khiếu nại","task":"You bought headphones online, but they arrived damaged and late. Write an email to the shop. Explain the problem and say what you want them to do.","taskVi":"Bạn mua tai nghe trên mạng nhưng hàng đến trễ và bị hỏng. Viết email cho cửa hàng: trình bày vấn đề và yêu cầu cách giải quyết.","min":120,"max":180,"outline":["Lý do viết email (đơn hàng số mấy, mua ngày nào)","Vấn đề 1: giao hàng trễ","Vấn đề 2: sản phẩm bị hỏng (mô tả cụ thể)","Yêu cầu: đổi hàng / hoàn tiền, trong thời gian bao lâu","Kết thư lịch sự"],"phrases":[["I am writing to complain about …","Tôi viết thư này để khiếu nại về …"],["According to your website, …","Theo trang web của quý cửa hàng, …"],["Unfortunately, …","Đáng tiếc là, …"],["I would like you to …","Tôi mong quý cửa hàng …"],["I look forward to hearing from you.","Tôi mong sớm nhận được phản hồi."],["Yours faithfully / sincerely,","Trân trọng,"]],"sample":"Dear Sir or Madam,\n\nI am writing to complain about an order I placed on your website on 3rd May (order number 58127). I bought a pair of SoundMax wireless headphones for 1,200,000 dong.\n\nAccording to your website, the delivery time was two days. However, the package did not arrive until 12th May, more than a week later. Unfortunately, that was not the only problem. When I opened the box, I found that the left side of the headband was cracked, and the right earphone did not produce any sound at all. I have attached two photos of the damage.\n\nI was disappointed, because I needed the headphones for an online course that started on 8th May. I would like you to send me a new pair as soon as possible, or give me a full refund if a replacement is not available. Please also tell me how to return the damaged product at no extra cost.\n\nI look forward to hearing from you.\n\nYours faithfully,\nNguyen Van Hieu"},{"id":"w-b1-goal","lv":3,"icon":"🎯","type":"Kế hoạch","t":"A goal for next year","vi":"Mục tiêu năm tới","task":"Write about an important goal you want to achieve next year. Why is it important? How will you achieve it? What problems might you face?","taskVi":"Viết về một mục tiêu quan trọng bạn muốn đạt được trong năm tới: vì sao quan trọng, bạn sẽ làm thế nào và có thể gặp khó khăn gì.","min":120,"max":180,"outline":["Mục tiêu là gì","Vì sao quan trọng với bạn","Kế hoạch cụ thể (các bước, thời gian)","Khó khăn có thể gặp + cách vượt qua","Kết: cảm nghĩ, quyết tâm"],"phrases":[["My main goal for next year is to …","Mục tiêu chính của tôi năm tới là …"],["This is important to me because …","Điều này quan trọng với tôi vì …"],["I'm going to …","Tôi định …"],["I'm planning to …","Tôi dự định …"],["The biggest challenge will be …","Thử thách lớn nhất sẽ là …"],["If …, I will …","Nếu …, tôi sẽ …"]],"sample":"My main goal for next year is to reach an IELTS score of 6.5. This is important to me because I would like to apply for a job at an international animation studio, and good English is necessary to communicate with directors and clients from other countries.\n\nI'm going to study for at least forty minutes every day. In the morning, I will listen to podcasts on my way to work, and in the evening I will practise writing and review new vocabulary with flashcards. I'm also planning to join a speaking club on Saturdays, because speaking is my weakest skill.\n\nThe biggest challenge will be finding time, since I sometimes have to work overtime when we have deadlines. If I miss a study session, I will not give up; I will just do a shorter one the next day. I know it will not be easy, but I believe that small steps every day will help me achieve my goal."},{"id":"w-b2-essay","lv":4,"icon":"⚖️","type":"Bài luận","t":"Social media: good or bad for young people?","vi":"Mạng xã hội tốt hay xấu cho giới trẻ?","task":"Discuss both the advantages and disadvantages of social media for young people, and give your own opinion.","taskVi":"Bàn về cả lợi ích và tác hại của mạng xã hội đối với giới trẻ, và nêu quan điểm của bạn.","min":180,"max":250,"outline":["Mở bài: giới thiệu vấn đề, cho biết sẽ bàn hai mặt","Thân bài 1: lợi ích (kết nối, học tập, sáng tạo) + ví dụ","Thân bài 2: tác hại (so sánh, mất tập trung, thông tin sai) + ví dụ","Kết bài: quan điểm cân bằng + đề xuất"],"phrases":[["It is undeniable that …","Không thể phủ nhận rằng …"],["One major benefit is that …","Một lợi ích lớn là …"],["Furthermore, …","Hơn nữa, …"],["However, there are also serious drawbacks.","Tuy nhiên cũng có những tác hại nghiêm trọng."],["This can lead to …","Điều này có thể dẫn đến …"],["On balance, I believe …","Cân nhắc mọi mặt, tôi tin rằng …"]],"sample":"Social media has become a central part of young people's lives, shaping how they communicate, learn and see themselves. While these platforms offer real benefits, they also carry risks that should not be ignored.\n\nOne major benefit is connection. Teenagers can stay in touch with friends who have moved away, and those who feel isolated, for example because of a rare hobby, can find supportive communities online. Furthermore, social media can be a powerful learning tool. Many young artists I know started sharing their drawings or 3D work online, received useful feedback and eventually found freelance clients.\n\nHowever, there are also serious drawbacks. Platforms are designed to keep users scrolling, which can reduce sleep and make it harder to concentrate on study. In addition, constantly seeing carefully edited photos of other people's lives can lead to unhealthy comparisons and low self-esteem. Misinformation is another concern, as false stories often spread faster than accurate ones.\n\nOn balance, I believe social media is neither simply good nor bad; its effect depends largely on how it is used. Rather than banning it, schools and parents should teach young people to manage their screen time, think critically about what they see, and use these tools to create rather than just consume."},{"id":"w-b2-report","lv":4,"icon":"📊","type":"Báo cáo","t":"Improving the workplace","vi":"Báo cáo cải thiện nơi làm việc","task":"Your manager has asked for a short report on how to improve staff wellbeing in your office. Describe the current situation and make recommendations.","taskVi":"Quản lý yêu cầu bạn viết một báo cáo ngắn về cách cải thiện sức khỏe, tinh thần của nhân viên trong văn phòng: mô tả hiện trạng và đưa ra đề xuất.","min":180,"max":250,"outline":["Tiêu đề + Mục đích báo cáo (Introduction)","Hiện trạng (Current situation): vấn đề chính, số liệu khảo sát nếu có","Đề xuất (Recommendations): 2–3 đề xuất cụ thể","Kết luận (Conclusion)"],"phrases":[["The aim of this report is to …","Mục đích của báo cáo này là …"],["According to a recent survey, …","Theo một khảo sát gần đây, …"],["A significant number of staff …","Một số lượng đáng kể nhân viên …"],["It is recommended that …","Đề xuất rằng …"],["This would allow …","Điều này sẽ giúp …"],["In conclusion, …","Tóm lại, …"]],"sample":"Staff Wellbeing Report\n\nIntroduction\nThe aim of this report is to describe the current level of staff wellbeing in our studio and to suggest practical improvements. It is based on an anonymous survey completed by 42 employees last month.\n\nCurrent situation\nAccording to the survey, 65% of staff regularly work more than nine hours a day during production deadlines, and over half reported back or eye pain. A significant number also said that the office feels crowded and noisy, which makes it difficult to concentrate on detailed tasks such as modelling and animation. On the positive side, most employees value their colleagues and feel proud of the projects they work on.\n\nRecommendations\nFirstly, it is recommended that the company plan deadlines more realistically and limit overtime to two evenings a week. Secondly, investing in adjustable chairs and monitor stands would reduce physical problems. Finally, converting the small meeting room into a quiet zone would allow artists to focus when necessary.\n\nConclusion\nIn conclusion, although team spirit is strong, long hours and the physical environment are affecting staff health. The measures above are relatively low-cost and would be likely to improve both wellbeing and productivity."},{"id":"w-b2-cover","lv":4,"icon":"💼","type":"Thư xin việc","t":"A cover letter","vi":"Thư xin việc","task":"Write a cover letter applying for a job you would like (for example, a 3D artist at an international studio). Explain why you are interested and why you are a good candidate.","taskVi":"Viết thư xin một công việc bạn mong muốn (ví dụ họa sĩ 3D ở một studio quốc tế): vì sao bạn quan tâm và vì sao bạn phù hợp.","min":180,"max":250,"outline":["Mở: ứng tuyển vị trí nào, biết tin ở đâu","Vì sao bạn quan tâm đến công ty / vị trí","Kinh nghiệm, kỹ năng nổi bật + thành tích cụ thể","Tính cách, khả năng làm việc nhóm, tiếng Anh","Kết: mong được phỏng vấn, cảm ơn"],"phrases":[["I am writing to apply for the position of …","Tôi viết thư này để ứng tuyển vị trí …"],["I was particularly impressed by …","Tôi đặc biệt ấn tượng với …"],["I have … years of experience in …","Tôi có … năm kinh nghiệm về …"],["I was responsible for …","Tôi phụ trách …"],["I would welcome the opportunity to …","Tôi rất mong có cơ hội …"],["Thank you for considering my application.","Cảm ơn quý công ty đã xem xét hồ sơ của tôi."]],"sample":"Dear Ms Taylor,\n\nI am writing to apply for the position of Junior 3D Environment Artist, which I saw advertised on your studio's website. I have followed Northlight Studio's work for several years, and I was particularly impressed by the atmospheric forests in your latest game, which combine realistic detail with a strong artistic style.\n\nI have three years of experience as a 3D artist at a mobile game company in Ho Chi Minh City. In my current role, I am responsible for modelling, UV unwrapping and texturing props and environments, while keeping assets within strict performance budgets. Last year, I redesigned our texture workflow, which reduced the size of our main level by 30% without a visible loss in quality.\n\nBeyond technical skills, I enjoy working closely with designers and programmers, and I am comfortable receiving feedback and adapting quickly. I also use English every day to communicate with our overseas publisher, so I am confident working in an international team.\n\nI have attached my CV and a link to my online portfolio. I would welcome the opportunity to discuss how I could contribute to your team. Thank you for considering my application.\n\nYours sincerely,\nNguyen Van Hieu"},{"id":"w-b2-problem","lv":4,"icon":"🚦","type":"Vấn đề – Giải pháp","t":"Traffic in big cities","vi":"Giao thông ở thành phố lớn","task":"Traffic congestion is a serious problem in many big cities. What are the causes, and what solutions can you suggest?","taskVi":"Ùn tắc giao thông là vấn đề nghiêm trọng ở nhiều thành phố lớn. Nguyên nhân là gì và bạn đề xuất giải pháp nào?","min":180,"max":250,"outline":["Mở bài: nêu vấn đề (ví dụ Hà Nội, TP.HCM)","Thân bài 1: 2 nguyên nhân chính + giải thích","Thân bài 2: 2–3 giải pháp tương ứng + ví dụ","Kết bài: tóm tắt, nhấn mạnh cần kết hợp nhiều biện pháp"],"phrases":[["… has become a pressing issue.","… đã trở thành vấn đề cấp bách."],["One of the main causes is …","Một trong những nguyên nhân chính là …"],["This is largely due to …","Điều này phần lớn là do …"],["One possible solution would be to …","Một giải pháp khả thi là …"],["If this were done, …","Nếu làm được điều này, …"],["A combination of measures is needed.","Cần kết hợp nhiều biện pháp."]],"sample":"In cities such as Ha Noi and Ho Chi Minh City, traffic congestion has become a pressing issue. Daily commutes that should take twenty minutes can last an hour, wasting time, fuel and patience.\n\nOne of the main causes is the rapid growth in private vehicles. As incomes rise, more families buy motorbikes and cars, but road space cannot expand at the same speed. Another cause is poor urban planning. Offices, schools and shopping centres are concentrated in a few central districts, so millions of people travel in the same direction at the same time.\n\nSeveral solutions could help. First, cities should invest heavily in reliable public transport. The new metro lines are a good start, but they need to be connected to frequent buses so that people can travel from door to door without a motorbike. Second, the government could introduce charges for driving into the city centre during rush hours, as cities like Singapore have done. If this were done, some drivers would change their travel times or switch to public transport. Finally, encouraging flexible working hours and working from home would spread journeys more evenly throughout the day.\n\nIn conclusion, there is no single answer to traffic congestion. A combination of better public transport, smarter pricing and new working habits is needed to make our cities easier to move around."},{"id":"w-c1-ai","lv":5,"icon":"🤖","type":"Bài luận","t":"AI and creative work","vi":"AI và công việc sáng tạo","task":"Some argue that AI tools will devalue the work of artists and designers; others believe they will free creators to focus on what matters most. Discuss both views and give your own opinion.","taskVi":"Có người cho rằng công cụ AI sẽ làm giảm giá trị công việc của họa sĩ, nhà thiết kế; người khác tin AI giúp người sáng tạo tập trung vào điều quan trọng nhất. Bàn về hai quan điểm và nêu ý kiến của bạn.","min":230,"max":320,"outline":["Mở bài: bối cảnh + tranh luận + luận điểm của bạn","Thân bài 1: quan điểm \"giảm giá trị\" (áp lực giá, bản quyền, kỹ năng bị bỏ qua)","Thân bài 2: quan điểm \"giải phóng\" (bỏ việc lặp lại, thử ý tưởng nhanh, vai trò định hướng)","Thân bài 3 (tuỳ chọn): điều kiện để mặt tích cực thắng thế","Kết bài: quan điểm rõ ràng, có sắc thái"],"phrases":[["Few developments have provoked as much debate as …","Ít có bước phát triển nào gây tranh cãi nhiều như …"],["Proponents of this view argue that …","Những người ủng hộ quan điểm này cho rằng …"],["There is some truth in this.","Điều này có phần đúng."],["That said, …","Dù vậy, …"],["What is at stake is …","Điều đang bị đe dọa là …"],["Ultimately, …","Rốt cuộc, …"]],"sample":"Few developments have provoked as much debate in creative industries as the rise of generative AI. Within months, tools that can produce illustrations, textures or even 3D models from a short description have moved from research labs into everyday workflows. Whether this devalues creative work or liberates it depends, I would argue, less on the technology itself than on how it is adopted.\n\nThose who fear devaluation make a serious case. When clients can obtain a passable image in seconds, the market price of routine illustration inevitably falls, and junior roles, traditionally the training ground for future experts, may be the first to disappear. There are also unresolved questions of consent and copyright, since many models were trained on artists' work without permission or payment.\n\nThat said, the history of creative tools suggests another possibility. Digital painting and 3D software were once accused of \"cheating\", yet they ultimately expanded what artists could achieve. In my own field, a large part of a 3D artist's time is spent on repetitive tasks such as UV unwrapping or creating variations of the same asset. Delegating such work to AI could leave more time for the decisions that genuinely require human judgement: composition, storytelling, and a coherent visual style.\n\nUltimately, I believe AI will raise the value of creative direction while lowering the value of pure execution. For this shift to benefit creators rather than only companies, however, fair rules on training data and a deliberate effort to keep training young artists will be essential."},{"id":"w-c1-proposal","lv":5,"icon":"🏛️","type":"Đề xuất","t":"A proposal for your city","vi":"Đề xuất cho thành phố","task":"Your city council is inviting proposals for a project to make the city more liveable. Write a proposal describing one project, explaining its benefits, and addressing possible objections.","taskVi":"Hội đồng thành phố mời người dân gửi đề xuất một dự án giúp thành phố đáng sống hơn. Viết đề xuất: mô tả dự án, lợi ích và trả lời các ý kiến phản đối có thể có.","min":230,"max":320,"outline":["Tiêu đề + Giới thiệu (mục đích)","Mô tả dự án (ở đâu, gồm những gì)","Lợi ích (môi trường, sức khỏe, kinh tế, cộng đồng)","Phản đối có thể có + cách giải quyết (chi phí, buôn bán, an toàn)","Kết luận + đề nghị hành động"],"phrases":[["The purpose of this proposal is to …","Mục đích của đề xuất này là …"],["The scheme would involve …","Dự án sẽ bao gồm …"],["Not only would this …, but it would also …","Điều này không chỉ …, mà còn …"],["Some may object that …","Có thể có ý kiến phản đối rằng …"],["This concern could be addressed by …","Mối lo ngại này có thể được giải quyết bằng …"],["I would therefore urge the council to …","Vì vậy tôi đề nghị hội đồng …"]],"sample":"Proposal: Weekend Car-Free Riverside\n\nIntroduction\nThe purpose of this proposal is to suggest a low-cost project that would give residents more safe, green public space: closing the riverside road between the two central bridges to motor traffic every weekend.\n\nThe project\nThe scheme would involve closing a 1.5-kilometre stretch from 6 a.m. on Saturday to 10 p.m. on Sunday. Temporary planters and benches would be placed along the road, and local groups would be invited to run activities such as exercise classes, children's games and small craft markets.\n\nBenefits\nNot only would this provide space for walking and cycling in a district with very few parks, but it would also reduce noise and air pollution along the river during the busiest leisure hours. Similar schemes elsewhere have attracted more visitors to nearby shops and cafés, and they encourage neighbours to spend time together outdoors.\n\nPossible objections\nSome may object that closing the road will cause congestion on surrounding streets. This concern could be addressed by running a three-month trial, publishing traffic data, and adjusting the hours if necessary. Business owners may worry about deliveries; allowing delivery vehicles before 9 a.m. would solve most problems. Finally, the cost would be modest, since the plan uses existing roads and movable furniture rather than new construction.\n\nConclusion\nA car-free riverside would offer an affordable way to test a greener, more people-friendly city centre. I would therefore urge the council to approve a trial for the coming dry season."},{"id":"w-c1-review","lv":5,"icon":"🎞️","type":"Bình luận","t":"Review a film or book","vi":"Bình luận phim hoặc sách","task":"Write a review of a film, series or book that made a strong impression on you. Briefly summarise it, analyse what makes it effective or flawed, and say who would appreciate it.","taskVi":"Viết bài bình luận về một bộ phim, series hoặc cuốn sách để lại ấn tượng mạnh: tóm tắt ngắn, phân tích điểm hay / dở và nói ai sẽ thích nó.","min":230,"max":320,"outline":["Mở bài: tên tác phẩm, thể loại, ấn tượng chung (một câu \"hook\")","Tóm tắt ngắn, không tiết lộ kết thúc","Phân tích điểm mạnh (nhân vật, hình ảnh, chủ đề…) có dẫn chứng","Điểm yếu / hạn chế","Kết luận: đánh giá tổng thể + nên dành cho ai"],"phrases":[["… is far more than …","… còn hơn nhiều so với …"],["Set in …, the story follows …","Lấy bối cảnh ở …, câu chuyện kể về …"],["What sets it apart is …","Điều làm nó khác biệt là …"],["Where it falls short is …","Điểm nó còn thiếu là …"],["Despite these flaws, …","Dù có những thiếu sót này, …"],["It will particularly appeal to …","Tác phẩm đặc biệt hợp với …"]],"sample":"Some films are remembered for their spectacle; the one I want to recommend is remembered for its silence. \"The Lighthouse Keeper\", a quiet animated feature I watched last year, is far more than a children's story about a lonely old man and a seagull.\n\nSet on a small island in a nameless northern sea, the story follows Elias, who has kept the same lighthouse running for forty years. When an automated system is announced that will make his job unnecessary, he has one winter left to decide what his life has meant. An injured seagull that he nurses back to health becomes his only companion.\n\nWhat sets the film apart is its restraint. There is almost no dialogue; emotion is carried instead by light. Long, carefully composed shots show the beam sweeping across a dark sea, while the warm interior of the lighthouse gradually grows colder as Elias loses hope. As a 3D artist, I was struck by how deliberately limited the colour palette is, and how much meaning the lighting team achieves with so little.\n\nWhere it falls short is in its pacing. The middle section repeats similar scenes for too long, and some viewers may find their attention drifting. The ending, while moving, is also somewhat predictable.\n\nDespite these flaws, the film offers a rare, contemplative experience in an industry often obsessed with speed and noise. It will particularly appeal to adults who enjoy slow cinema, and to anyone interested in visual storytelling."},{"id":"w-c1-reflect","lv":5,"icon":"🪞","type":"Suy ngẫm","t":"A lesson from failure","vi":"Bài học từ thất bại","task":"Reflect on a time when you failed at something important. What happened, what did you learn, and how has it changed the way you work or think?","taskVi":"Suy ngẫm về một lần bạn thất bại trong việc quan trọng: chuyện gì đã xảy ra, bạn học được gì, và điều đó thay đổi cách bạn làm việc hay suy nghĩ ra sao.","min":230,"max":320,"outline":["Mở bài: giới thiệu trải nghiệm + câu dẫn dắt","Bối cảnh và diễn biến thất bại (ngắn gọn, cụ thể)","Phân tích nguyên nhân: lỗi của bạn, yếu tố bên ngoài","Bài học rút ra","Thay đổi lâu dài + suy nghĩ hiện tại"],"phrases":[["At the time, I was convinced that …","Lúc đó tôi tin chắc rằng …"],["In hindsight, …","Nhìn lại thì …"],["It was only later that I realised …","Mãi sau này tôi mới nhận ra …"],["The experience taught me …","Trải nghiệm đó dạy tôi …"],["These days, I make a point of …","Giờ đây tôi luôn chú ý …"],["I have come to see … as …","Tôi dần coi … là …"]],"sample":"Three years ago, I was dismissed from a project I had been proud to join. At the time, I was convinced that it was simply bad luck; it took me months to admit that it was largely my own fault.\n\nI had been hired as a freelance 3D artist to create characters for a small mobile game. Eager to impress the client, I agreed to every request and every deadline without question. Instead of sharing rough drafts, I spent weeks polishing the first character in secret, adding detail that nobody had asked for. When I finally presented it, the art director explained that the style no longer matched the game, which had changed direction while I was working. By then, the budget for my part was almost gone, and they decided to continue without me.\n\nIn hindsight, the problem was not my technical ability but my fear of showing unfinished work. I had treated feedback as a judgement on my talent rather than as information that would save time. I also failed to ask the questions that would have revealed the change in direction.\n\nThe experience taught me that communication is part of the craft, not a distraction from it. These days, I make a point of sharing simple blockouts within the first few days of any task, agreeing on clear milestones, and asking \"What has changed?\" at every meeting. My work is not necessarily more beautiful than before, but it is far more often what the client actually needs.\n\nI have come to see that failure as one of the most useful things that has happened to my career."}];
/* ============================================================
   VIẾT THEO ĐỀ A1–C1 (v146) — 20 đề tự soạn: dàn ý, cụm từ, bài mẫu
   ✨ AI chấm bằng khoá của chính bạn (Gemini / Groq / ChatGPT, cài ở tab Nói chuyện)
   🔍 Kiểm tra nhanh miễn phí bằng LanguageTool. Lỗi AI tìm được → Sổ lỗi.
============================================================ */
(function () {
  const root = document.getElementById('rd-root');
  if (!root || typeof WR_TASKS === 'undefined') return;
  const E = (tag, cls, text) => { const e = document.createElement(tag); if (cls) e.className = cls; if (text != null) e.textContent = text; return e; };
  const KEY = 'hoc-tieng-anh-write', LVK = 'hoc-tieng-anh-write-lv';
  const LV = ['A1', 'A2', 'B1', 'B2', 'C1'];
  let prog = {}; try { prog = JSON.parse(localStorage.getItem(KEY) || '{}') || {}; } catch (e) {}
  let saveT = 0;
  const save = now => { clearTimeout(saveT); const f = () => { try { localStorage.setItem(KEY, JSON.stringify(prog)); } catch (e) {} }; if (now) f(); else saveT = setTimeout(f, 500); };
  const P = id => prog[id] || (prog[id] = { d: '', h: [] });
  let lvF = 0; try { const v = +localStorage.getItem(LVK); if (v >= 0 && v <= 5) lvF = v; } catch (e) {}
  const wc = s => (String(s).match(/[A-Za-z0-9][A-Za-z0-9'’-]*/g) || []).length;
  const top = () => { const m = document.querySelector('main'); window.scrollTo({ top: m ? Math.max(0, m.offsetTop - 8) : 0 }); };
  const say = t => { try { if (typeof speak === 'function') speak(t, 0.9); } catch (e) {} };

  // ---- AI dùng chung với tab Nói chuyện ----
  async function ai() {
    if (!window.aiAPI && window.appLoadTab) { try { await window.appLoadTab('page-talk'); } catch (e) {} }
    return window.aiAPI || null;
  }
  const SCHEMA = { type: 'OBJECT', properties: {
    score: { type: 'NUMBER' }, cefr: { type: 'STRING' },
    s_task: { type: 'NUMBER' }, n_task: { type: 'STRING' }, s_coh: { type: 'NUMBER' }, n_coh: { type: 'STRING' },
    s_voc: { type: 'NUMBER' }, n_voc: { type: 'STRING' }, s_gram: { type: 'NUMBER' }, n_gram: { type: 'STRING' },
    praise: { type: 'STRING' },
    errors: { type: 'ARRAY', items: { type: 'OBJECT', properties: { wrong: { type: 'STRING' }, right: { type: 'STRING' }, why: { type: 'STRING' } }, required: ['wrong', 'right', 'why'] } },
    tips: { type: 'ARRAY', items: { type: 'STRING' } }, improved: { type: 'STRING' } },
    required: ['score', 'cefr', 's_task', 'n_task', 's_coh', 'n_coh', 's_voc', 'n_voc', 's_gram', 'n_gram', 'praise', 'errors', 'tips', 'improved'],
    propertyOrdering: ['score', 'cefr', 's_task', 'n_task', 's_coh', 'n_coh', 's_voc', 'n_voc', 's_gram', 'n_gram', 'praise', 'errors', 'tips', 'improved'] };
  const SYS = [
    'You are an experienced, encouraging English writing teacher for Vietnamese adult learners.',
    'Evaluate the learner\'s text for the given task and target CEFR level. Be fair and realistic: a text that fully meets the target level deserves 7–8; 9–10 only for excellent work.',
    'Scores 0–10 (one decimal allowed): score = overall; s_task = task achievement (answers every part, right length and format); s_coh = coherence & organisation; s_voc = vocabulary range and accuracy; s_gram = grammar range and accuracy.',
    'n_task, n_coh, n_voc, n_gram, praise, tips and every "why" MUST be written in Vietnamese, short and concrete (1–2 sentences).',
    'errors: up to 12 of the most important mistakes (grammar, word choice, spelling, unnatural phrasing). "wrong" must be copied EXACTLY, character for character, from the learner\'s text (a short phrase, not the whole paragraph); "right" is the corrected phrase.',
    'improved: rewrite the whole text in natural English at the target level, keeping the learner\'s ideas, order and paragraphing. Do not make it much longer.',
    'cefr: your estimate of the level shown by this text (A1, A2, B1, B2, C1 or C2). tips: 2–3 practical suggestions.',
    'Return only JSON.'
  ].join('\n');
  const levelNote = l => ['very simple sentences, present simple, basic vocabulary', 'simple connected sentences, past simple, common linkers', 'clear paragraphs, a range of tenses, opinions with reasons', 'well-organised text, complex sentences, precise vocabulary, formal/informal register', 'sophisticated, nuanced writing, wide range of structures and idiomatic language'][l - 1];

  /* ---------- danh sách đề ---------- */
  function home(header) {
    root.innerHTML = '';
    if (header) root.appendChild(header);
    const sum = E('div', 'tense-card rd-sum');
    const done = WR_TASKS.filter(w => prog[w.id] && prog[w.id].best != null).length;
    sum.appendChild(E('div', 'rd-sum-t', `Đã viết ${done}/${WR_TASKS.length} đề`));
    sum.appendChild(E('div', 'rv-note', 'Mỗi đề có dàn ý, cụm từ nên dùng và bài mẫu. Viết xong bấm ✨ AI chấm bài (dùng khoá AI miễn phí của bạn) hoặc 🔍 Kiểm tra nhanh.'));
    root.appendChild(sum);
    const chips = E('div', 'colloc-chips rd-chips');
    [['Tất cả', 0], ...LV.map((x, i) => [x, i + 1])].forEach(([name, v]) => {
      const n = WR_TASKS.filter(w => !v || w.lv === v), d = n.filter(w => prog[w.id] && prog[w.id].best != null).length;
      const b = E('button', 'colloc-chip' + (lvF === v ? ' active' : ''), `${name} · ${d}/${n.length}`); b.type = 'button';
      b.addEventListener('click', () => { lvF = v; try { localStorage.setItem(LVK, String(v)); } catch (e) {} window.rdHome('write'); });
      chips.appendChild(b);
    });
    root.appendChild(chips);
    const grid = E('div', 'rd-grid');
    WR_TASKS.filter(w => !lvF || w.lv === lvF).forEach(w => {
      const p = prog[w.id], c = E('button', 'rd-card' + (p && p.best != null ? ' done' : '')); c.type = 'button';
      const h = E('div', 'rd-card-h'); h.appendChild(E('span', 'rd-ic', w.icon)); h.appendChild(E('span', 'rd-lv', LV[w.lv - 1]));
      if (p && p.best != null) h.appendChild(E('span', 'rd-st ' + (p.best >= 7 ? 'ok' : 'mid'), `✓ ${p.best}/10`));
      else if (p && p.d && p.d.trim()) h.appendChild(E('span', 'rd-st nx', 'Bản nháp'));
      c.appendChild(h);
      c.appendChild(E('div', 'rd-card-t', w.t));
      c.appendChild(E('div', 'rd-card-vi', w.vi));
      c.appendChild(E('div', 'rd-card-m', `${w.type} · ${w.min}–${w.max} từ`));
      c.addEventListener('click', () => { task(w); top(); });
      grid.appendChild(c);
    });
    root.appendChild(grid);
  }

  /* ---------- một đề ---------- */
  function task(w) {
    root.innerHTML = '';
    const p = P(w.id);
    const back = E('button', 'gr-back', '← Viết theo đề'); back.type = 'button'; back.addEventListener('click', () => { save(true); window.rdHome('write'); top(); });
    root.appendChild(back);
    const head = E('div', 'gr-head');
    head.appendChild(E('div', 'gr-en', `${LV[w.lv - 1]} · ${w.type} · ${w.min}–${w.max} từ`));
    head.appendChild(E('h2', 'gr-title', w.icon + ' ' + w.t));
    head.appendChild(E('div', 'rd-vi-t', w.vi));
    root.appendChild(head);
    const tc = E('div', 'tense-card wr-task');
    tc.appendChild(E('div', 'wr-task-en', w.task));
    tc.appendChild(E('div', 'wr-task-vi', w.taskVi));
    const ol = E('details', 'wr-det'); ol.appendChild(E('summary', null, '🧭 Dàn ý gợi ý'));
    const ul = E('ul', 'wr-ol'); w.outline.forEach(x => ul.appendChild(E('li', null, x))); ol.appendChild(ul);
    tc.appendChild(ol);
    const ph = E('details', 'wr-det'); ph.appendChild(E('summary', null, '🧩 Cụm từ nên dùng · chạm để chèn'));
    const pw = E('div', 'wr-ph');
    tc.appendChild(ph);
    root.appendChild(tc);

    const ta = E('textarea', 'wr-ta'); ta.rows = 10; ta.placeholder = 'Viết bài của bạn bằng tiếng Anh ở đây… (tự lưu bản nháp)';
    ta.spellcheck = false; ta.setAttribute('autocapitalize', 'sentences'); ta.value = p.d || '';
    w.phrases.forEach(([en, vi]) => {
      const b = E('button', 'rd-gli'); b.type = 'button'; b.appendChild(E('b', null, en)); b.appendChild(E('span', null, vi));
      b.addEventListener('click', () => {
        const ins = en.replace(/\s*…\s*/g, ' ').replace(/\s+([.,?!])/g, '$1').trim() + ' ';
        const s = ta.selectionStart != null ? ta.selectionStart : ta.value.length, e2 = ta.selectionEnd != null ? ta.selectionEnd : s;
        const pre = ta.value.slice(0, s), pad = pre && !/\s$/.test(pre) ? ' ' : '';
        ta.value = pre + pad + ins + ta.value.slice(e2); ta.focus(); const pos = (pre + pad + ins).length; try { ta.setSelectionRange(pos, pos); } catch (x) {}
        ta.dispatchEvent(new Event('input'));
      });
      pw.appendChild(b);
    });
    ph.appendChild(pw);
    const wrap = E('div', 'tense-card wr-edit');
    wrap.appendChild(ta);
    const meta = E('div', 'wr-meta');
    const cnt = E('span', 'wr-cnt');
    const upd = () => { const n = wc(ta.value); cnt.textContent = `${n} từ · yêu cầu ${w.min}–${w.max}`; cnt.className = 'wr-cnt ' + (n === 0 ? '' : n < w.min ? 'low' : n > w.max * 1.2 ? 'high' : 'ok'); };
    ta.addEventListener('input', () => { p.d = ta.value; save(); upd(); });
    upd();
    meta.appendChild(cnt);
    wrap.appendChild(meta);
    const acts = E('div', 'wr-acts');
    const bAI = E('button', 'btn-primary', '✨ AI chấm bài'); bAI.type = 'button';
    const bLT = E('button', 'btn-ghost', '🔍 Kiểm tra nhanh'); bLT.type = 'button';
    const bS = E('button', 'btn-ghost', '📄 Bài mẫu'); bS.type = 'button';
    acts.appendChild(bAI); acts.appendChild(bLT); acts.appendChild(bS);
    wrap.appendChild(acts);
    root.appendChild(wrap);
    const out = E('div', 'wr-out'); root.appendChild(out);
    const sampleBox = E('div', 'tense-card wr-sample'); sampleBox.hidden = true; root.appendChild(sampleBox);

    // bài mẫu
    bS.addEventListener('click', () => {
      if (!sampleBox.hidden) { sampleBox.hidden = true; return; }
      if (!wc(ta.value) && !confirm('Bạn chưa viết gì. Xem bài mẫu ngay bây giờ? (Nên tự viết trước rồi mới so sánh.)')) return;
      sampleBox.innerHTML = '';
      const h = E('div', 'wr-sh'); h.appendChild(E('h3', null, '📄 Bài mẫu (' + wc(w.sample) + ' từ)'));
      const pl = E('button', 'btn-ghost', '🔊 Nghe'); pl.type = 'button'; pl.addEventListener('click', () => say(w.sample.replace(/\n+/g, ' '))); h.appendChild(pl);
      sampleBox.appendChild(h);
      w.sample.split(/\n+/).forEach(par => sampleBox.appendChild(E('p', 'wr-sp', par)));
      sampleBox.appendChild(E('div', 'rv-note', 'Bài mẫu chỉ là một cách viết. Bài của bạn có ý khác vẫn tốt, miễn là trả lời đủ đề.'));
      sampleBox.hidden = false;
      try { sampleBox.scrollIntoView({ behavior: 'smooth', block: 'start' }); } catch (e) {}
    });

    // kiểm tra nhanh (LanguageTool, miễn phí)
    bLT.addEventListener('click', async () => {
      const t = ta.value.trim(); if (!t) { ta.focus(); return; }
      if (typeof fxLanguageTool !== 'function') return;
      bLT.disabled = true; bLT.textContent = 'Đang kiểm tra…';
      out.innerHTML = '';
      let r = null; try { r = await fxLanguageTool(t); } catch (e) {}
      bLT.disabled = false; bLT.textContent = '🔍 Kiểm tra nhanh';
      const c = E('div', 'tense-card wr-lt');
      c.appendChild(E('h3', null, '🔍 Kiểm tra nhanh (chính tả, ngữ pháp cơ bản)'));
      if (r === 'busy') c.appendChild(E('div', 'rv-note', 'Dịch vụ kiểm tra đang bận. Đợi khoảng một phút rồi thử lại.'));
      else if (!Array.isArray(r)) c.appendChild(E('div', 'rv-note', 'Không kiểm tra được. Phần này cần kết nối mạng.'));
      else if (!r.length) c.appendChild(E('div', 'rv-note', '✓ Không thấy lỗi chính tả hay ngữ pháp cơ bản. Bấm ✨ AI chấm bài để được nhận xét sâu hơn về nội dung, từ vựng và cách diễn đạt.'));
      else {
        const l = E('ul', 'wr-errs');
        r.slice(0, 20).forEach(x => { const li = E('li'); li.appendChild(E('s', null, x.orig)); li.appendChild(document.createTextNode(' → ')); li.appendChild(E('b', null, x.rep)); if (x.msg) li.appendChild(E('div', 'wr-why', x.msg)); l.appendChild(li); });
        c.appendChild(l);
        c.appendChild(E('div', 'rv-note', 'Công cụ tự động chỉ bắt lỗi bề mặt. Bấm ✨ AI chấm bài để được giải thích bằng tiếng Việt.'));
      }
      try { if (window.actLog) actLog('w'); } catch (e) {}
      out.appendChild(c);
    });

    // AI chấm
    bAI.addEventListener('click', async () => {
      const t = ta.value.trim(); if (!t) { ta.focus(); return; }
      if (wc(t) < Math.max(10, Math.round(w.min * 0.4)) && !confirm(`Bài mới có ${wc(t)} từ (yêu cầu ${w.min}–${w.max}). Vẫn chấm?`)) return;
      out.innerHTML = '';
      const wait = E('div', 'tense-card wr-wait', '⏳ Đang kết nối AI…'); out.appendChild(wait);
      bAI.disabled = true;
      const A = await ai();
      if (!A) { wait.textContent = 'Không tải được phần AI. Kiểm tra mạng rồi thử lại.'; bAI.disabled = false; return; }
      if (!A.hasKey()) {
        wait.innerHTML = '';
        wait.appendChild(E('div', 'wr-need', '🔑 Cần cài khoá AI một lần (Gemini hoặc Groq đều miễn phí). Khoá chỉ lưu trên máy bạn.'));
        const s = E('button', 'btn-primary', 'Cài khoá AI →'); s.type = 'button'; s.addEventListener('click', () => { save(true); A.setup(); });
        wait.appendChild(s); bAI.disabled = false; return;
      }
      wait.textContent = `⏳ ${A.name()} đang chấm bài… (thường mất 5–20 giây)`;
      const user = `Task (target level ${LV[w.lv - 1]}: ${levelNote(w.lv)}; required length ${w.min}–${w.max} words; text type: ${w.type}):\n${w.task}\n\nLearner's text (${wc(t)} words):\n"""\n${t}\n"""`;
      let r = null, err = null;
      try { r = await A.json(SYS, user, SCHEMA, { temperature: 0.2, onRetry: n => { wait.textContent = n >= 2 ? '⏳ Máy chủ bận, đang đổi sang model khác…' : '⏳ Đang thử lại…'; } }); } catch (e) { err = e; }
      bAI.disabled = false;
      if (!r || typeof r !== 'object' || r.score == null) {
        wait.innerHTML = '';
        wait.appendChild(E('div', 'wr-need', '⚠️ ' + (err ? A.errText(err) : 'AI trả lời không đúng định dạng. Bấm chấm lại nhé.')));
        return;
      }
      wait.remove();
      try { if (window.actLog) actLog('w', 3); } catch (e) {}
      const sc = Math.max(0, Math.min(10, Math.round(+r.score * 10) / 10));
      p.h = (p.h || []).concat([{ t: Date.now(), s: sc, c: String(r.cefr || '').slice(0, 3), n: wc(t) }]).slice(-10);
      p.best = Math.max(p.best || 0, sc); save(true);
      out.appendChild(report(w, t, r, sc));
    });

    // lịch sử
    if (p.h && p.h.length) {
      const hb = E('div', 'rv-note wr-hist', 'Các lần chấm: ' + p.h.slice(-5).map(x => `${x.s}/10${x.c ? ' (' + x.c + ')' : ''} · ${new Date(x.t).getDate()}/${new Date(x.t).getMonth() + 1}`).join('  ·  '));
      root.insertBefore(hb, out);
    }
  }

  function report(w, text, r, sc) {
    const TXT = text;
    const box = E('div', 'wr-rep');
    const top1 = E('div', 'tense-card gx-score ' + (sc >= 7 ? 'ok' : sc >= 5 ? 'mid' : 'bad'));
    top1.appendChild(E('div', 'gx-score-t', 'Điểm tổng'));
    top1.appendChild(E('div', 'gx-score-big', `${sc}/10`));
    top1.appendChild(E('div', 'gx-score-sub', `Trình độ thể hiện trong bài: khoảng ${String(r.cefr || '?').toUpperCase()} · đề ${LV[w.lv - 1]}`));
    if (r.praise) top1.appendChild(E('div', 'gx-score-msg', '👍 ' + r.praise));
    box.appendChild(top1);
    const cr = E('div', 'tense-card wr-crit');
    cr.appendChild(E('h3', null, '📋 Theo từng tiêu chí'));
    [['Hoàn thành yêu cầu', r.s_task, r.n_task], ['Mạch lạc, bố cục', r.s_coh, r.n_coh], ['Từ vựng', r.s_voc, r.n_voc], ['Ngữ pháp', r.s_gram, r.n_gram]].forEach(([name, s, n]) => {
      const v = Math.max(0, Math.min(10, +s || 0));
      const row = E('div', 'db-sk');
      const h = E('div', 'db-sk-h'); h.appendChild(E('span', 'db-sk-n', name)); h.appendChild(E('span', 'db-sk-v', `${Math.round(v * 10) / 10}/10`)); row.appendChild(h);
      const bar = E('div', 'db-bar wr-bar'); const f = E('span', 'db-fill'); f.style.width = v * 10 + '%'; bar.appendChild(f); row.appendChild(bar);
      if (n) row.appendChild(E('div', 'db-sk-d', n));
      cr.appendChild(row);
    });
    box.appendChild(cr);
    const errs = (Array.isArray(r.errors) ? r.errors : []).filter(x => x && x.wrong && x.right && String(x.wrong).trim() !== String(x.right).trim() && TXT.includes(String(x.wrong)));   // bỏ lỗi AI tự bịa (không có trong bài)
    if (errs.length) {
      const ec = E('div', 'tense-card wr-errc');
      ec.appendChild(E('h3', null, `✏️ ${errs.length} lỗi cần sửa`));
      // bài của bạn, tô các chỗ sai
      const mk = E('div', 'wr-marked');
      let html = [{ t: text }];
      errs.forEach((x, i) => {
        const wrong = String(x.wrong);
        for (let k = 0; k < html.length; k++) {
          const seg = html[k]; if (seg.m != null) continue;
          const at = seg.t.indexOf(wrong); if (at < 0) continue;
          html.splice(k, 1, { t: seg.t.slice(0, at) }, { t: wrong, m: i }, { t: seg.t.slice(at + wrong.length) });
          break;
        }
      });
      html.forEach(seg => { if (seg.m != null) { const m = E('mark', 'wr-mk', seg.t); m.title = '→ ' + errs[seg.m].right; m.dataset.n = seg.m + 1; mk.appendChild(m); } else mk.appendChild(document.createTextNode(seg.t)); });
      ec.appendChild(mk);
      const ol = E('ol', 'wr-errs');
      errs.forEach((x, i) => {
        const li = E('li');
        li.appendChild(E('s', null, x.wrong)); li.appendChild(document.createTextNode(' → ')); li.appendChild(E('b', null, x.right));
        if (x.why) li.appendChild(E('div', 'wr-why', x.why));
        ol.appendChild(li);
        // Sổ lỗi: câu chứa lỗi → câu đã sửa
        try {
          if (window.mkAdd) {
            const sents = text.match(/[^.!?\n]+[.!?]*/g) || [text];
            const s0 = (sents.find(s => s.includes(x.wrong)) || x.wrong).trim();
            window.mkAdd({ k: 'wr|' + w.id + '|' + String(x.wrong).toLowerCase().slice(0, 80), src: 'wr', cat: LV[w.lv - 1] + ' · ' + w.t, mode: 'fix', p: s0, a: [s0.replace(x.wrong, x.right)], why: x.why || '' });
          }
        } catch (e) {}
      });
      ec.appendChild(ol);
      ec.appendChild(E('div', 'rv-note', 'Các lỗi này đã được ghi vào 📕 Sổ lỗi để bạn luyện lại.'));
      box.appendChild(ec);
    }
    if (r.improved) {
      const ic = E('div', 'tense-card wr-imp');
      const h = E('div', 'wr-sh'); h.appendChild(E('h3', null, '✨ Bản viết lại tự nhiên hơn'));
      const pl = E('button', 'btn-ghost', '🔊 Nghe'); pl.type = 'button'; pl.addEventListener('click', () => say(String(r.improved).replace(/\n+/g, ' '))); h.appendChild(pl);
      ic.appendChild(h);
      String(r.improved).split(/\n+/).forEach(par => { if (par.trim()) ic.appendChild(E('p', 'wr-sp', par)); });
      box.appendChild(ic);
    }
    if (Array.isArray(r.tips) && r.tips.length) {
      const tc = E('div', 'tense-card');
      tc.appendChild(E('h3', null, '💡 Lần sau nên'));
      const ul = E('ul', 'wr-ol'); r.tips.slice(0, 4).forEach(x => ul.appendChild(E('li', null, String(x)))); tc.appendChild(ul);
      box.appendChild(tc);
    }
    box.appendChild(E('p', 'rv-note', 'Điểm do AI ước lượng, có thể chênh lệch giữa các lần chấm. Dùng để biết cần cải thiện gì, không thay cho giáo viên.'));
    setTimeout(() => { try { top1.scrollIntoView({ behavior: 'smooth', block: 'start' }); } catch (e) {} }, 50);
    return box;
  }
  window.wrHome = home;
  window.wrOpen = id => { const w = WR_TASKS.find(x => x.id === id); if (w) task(w); };
})();
