(function () {
  const root = document.getElementById('rd-root');
  if (!root || typeof LS_DIALOGS === 'undefined') return;
  const E = (tag, cls, text) => { const e = document.createElement(tag); if (cls) e.className = cls; if (text != null) e.textContent = text; return e; };
  const KEY = 'hoc-tieng-anh-listen2', LVK = 'hoc-tieng-anh-listen2-lv';
  const LV = ['A1', 'A2', 'B1', 'B2', 'C1'], RATE = [0.8, 0.85, 0.92, 0.97, 1];
  let prog = {}; try { prog = JSON.parse(localStorage.getItem(KEY) || '{}') || {}; } catch (e) {}
  const save = () => { try { localStorage.setItem(KEY, JSON.stringify(prog)); } catch (e) {} };
  let lvF = 0; try { const v = +localStorage.getItem(LVK); if (v >= 0 && v <= 5) lvF = v; } catch (e) {}
  const top = () => { const m = document.querySelector('main'); window.scrollTo({ top: m ? Math.max(0, m.offsetTop - 8) : 0 }); };
  const OPTS = { tf: ['True (Đúng)', 'False (Sai)'], tfng: ['True (Đúng)', 'False (Sai)', 'Not Given (Không có thông tin)'] };
  const opts = q => q.k === 'mc' ? q.o : OPTS[q.k];
  let play = null;
  const stop = () => { if (play) { play.stop = true; play = null; } try { speechSynthesis.cancel(); } catch (e) {} };
  document.querySelectorAll('nav.tabbar button').forEach(b => b.addEventListener('click', () => { if (b.dataset.page !== 'page-read') stop(); }));

  // giọng nam / nữ: lấy từ bộ chọn giọng của app; máy chỉ có một giọng thì đổi cao độ cho dễ phân biệt
  function voiceFor(g) {
    let v = null;
    try { const R = typeof vResolved !== 'undefined' ? vResolved : {}; v = g === 'm' ? (R['us-m'] || R['gb-m']) : (R['us-f'] || R['gb-f']); } catch (e) {}
    try { if (!v && typeof pronVoice !== 'undefined') v = pronVoice; } catch (e) {}
    return v || null;
  }
  function sayLine(l, i, rate, onEnd) {
    const [sp, text] = l.lines[i], g = (l.who[sp] || ['', 'f'])[1];
    const vA = voiceFor(l.who.A[1]), vB = voiceFor(l.who.B[1]);
    const v = sp === 'A' ? vA : vB;
    const u = new SpeechSynthesisUtterance(text);
    if (v) { u.voice = v; u.lang = (v.lang || 'en-US').replace('_', '-'); } else u.lang = 'en-US';
    u.rate = typeof ttsRate === 'function' ? ttsRate(rate) : rate;
    u.pitch = (vA && vB && vA.voiceURI === vB.voiceURI) ? (sp === 'B' ? (g === 'm' ? 0.75 : 1.25) : 1) : 1;
    let done = false; const fin = () => { if (done) return; done = true; if (onEnd) setTimeout(onEnd, 250); };
    u.addEventListener('end', fin); u.addEventListener('error', e => { if (e && (e.error === 'interrupted' || e.error === 'canceled')) { done = true; return; } fin(); });
    setTimeout(() => { if (!done && !speechSynthesis.speaking && !speechSynthesis.pending) fin(); }, 20000);
    if (typeof ttsPlay === 'function') ttsPlay(u); else speechSynthesis.speak(u);
  }

  function home(header) {
    stop();
    root.innerHTML = '';
    if (header) root.appendChild(header);
    const done = LS_DIALOGS.filter(l => prog[l.id] && prog[l.id].best != null).length;
    const sum = E('div', 'tense-card rd-sum');
    sum.appendChild(E('div', 'rd-sum-t', `Đã nghe ${done}/${LS_DIALOGS.length} hội thoại`));
    sum.appendChild(E('div', 'rv-note', 'Nghe hội thoại do máy đọc bằng hai giọng, rồi trả lời câu hỏi. Lời thoại được ẩn để bạn luyện nghe thật; nghe 2 lần rồi mới xem nhé.'));
    root.appendChild(sum);
    const chips = E('div', 'colloc-chips rd-chips');
    [['Tất cả', 0], ...LV.map((x, i) => [x, i + 1])].forEach(([name, v]) => {
      const n = LS_DIALOGS.filter(l => !v || l.lv === v), d = n.filter(l => prog[l.id] && prog[l.id].best != null).length;
      const b = E('button', 'colloc-chip' + (lvF === v ? ' active' : ''), `${name} · ${d}/${n.length}`); b.type = 'button';
      b.addEventListener('click', () => { lvF = v; try { localStorage.setItem(LVK, String(v)); } catch (e) {} window.rdHome('listen'); });
      chips.appendChild(b);
    });
    root.appendChild(chips);
    const grid = E('div', 'rd-grid');
    LS_DIALOGS.filter(l => !lvF || l.lv === lvF).forEach(l => {
      const p = prog[l.id], c = E('button', 'rd-card' + (p && p.best != null ? ' done' : '')); c.type = 'button';
      const h = E('div', 'rd-card-h'); h.appendChild(E('span', 'rd-ic', l.icon)); h.appendChild(E('span', 'rd-lv', LV[l.lv - 1]));
      if (p && p.best != null) h.appendChild(E('span', 'rd-st ' + (p.best >= 75 ? 'ok' : 'mid'), `✓ ${p.best}%`));
      c.appendChild(h);
      c.appendChild(E('div', 'rd-card-t', l.t));
      c.appendChild(E('div', 'rd-card-vi', l.vi));
      c.appendChild(E('div', 'rd-card-m', `${l.topic} · ${l.who.A[0]} & ${l.who.B[0]} · ${l.q.length} câu hỏi`));
      c.addEventListener('click', () => { lesson(l); top(); });
      grid.appendChild(c);
    });
    root.appendChild(grid);
  }

  function lesson(l) {
    stop();
    root.innerHTML = '';
    const P = prog[l.id] || {};
    const back = E('button', 'gr-back', '← Nghe hội thoại'); back.type = 'button'; back.addEventListener('click', () => { stop(); window.rdHome('listen'); top(); });
    root.appendChild(back);
    const head = E('div', 'gr-head');
    head.appendChild(E('div', 'gr-en', `${LV[l.lv - 1]} · ${l.topic} · ${l.lines.length} lượt lời`));
    head.appendChild(E('h2', 'gr-title', l.icon + ' ' + l.t));
    head.appendChild(E('div', 'rd-vi-t', l.vi));
    root.appendChild(head);
    const gv = g => g === 'm' ? 'giọng nam' : 'giọng nữ';
    const card = E('div', 'tense-card ls-player');
    card.appendChild(E('div', 'ls-who', `🗣 ${l.who.A[0]} (${gv(l.who.A[1])}) · ${l.who.B[0]} (${gv(l.who.B[1])})`));
    const bar = E('div', 'rd-bar');
    const pb = E('button', 'btn-primary ls-play', '▶ Nghe hội thoại'); pb.type = 'button';
    const slow = E('button', 'btn-ghost', '🐢 Chậm'); slow.type = 'button';
    const tr = E('button', 'btn-ghost', '👁 Hiện lời thoại'); tr.type = 'button';
    bar.appendChild(pb); bar.appendChild(slow); bar.appendChild(tr);
    card.appendChild(bar);
    const cnt = E('div', 'rv-note', 'Chưa nghe lần nào.');
    card.appendChild(cnt);
    const box = E('div', 'ls-lines'); box.hidden = true;
    const rows = l.lines.map(([sp, text], i) => {
      const r = E('button', 'ls-line ' + (sp === 'A' ? 'a' : 'b')); r.type = 'button';
      r.appendChild(E('span', 'ls-sp', l.who[sp][0]));
      r.appendChild(E('span', 'ls-tx', text));
      r.addEventListener('click', () => { stop(); mark(i); sayLine(l, i, rate(), () => mark(-1)); });
      box.appendChild(r);
      return r;
    });
    card.appendChild(box);
    root.appendChild(card);
    let slowOn = false, times = 0;
    const rate = () => RATE[l.lv - 1] * (slowOn ? 0.78 : 1);
    slow.addEventListener('click', () => { slowOn = !slowOn; slow.classList.toggle('active', slowOn); });
    tr.addEventListener('click', () => { box.hidden = !box.hidden; tr.textContent = box.hidden ? '👁 Hiện lời thoại' : '🙈 Ẩn lời thoại'; });
    const mark = i => rows.forEach((r, k) => r.classList.toggle('reading', k === i));
    const playFrom = (i0, only) => {
      stop();
      const S = play = { stop: false };
      pb.textContent = '⏹ Dừng';
      let i = i0;
      const nx = () => {
        if (S.stop || i >= l.lines.length || (only != null && i > only)) {
          mark(-1);
          if (play === S) { play = null; pb.textContent = '▶ Nghe lại'; if (only == null && i >= l.lines.length) { times++; cnt.textContent = `Đã nghe ${times} lần.` + (times === 1 ? ' Nghe thêm một lần nữa rồi trả lời câu hỏi nhé.' : ''); try { if (window.actLog) actLog('l'); } catch (e) {} } }
          return;
        }
        mark(i);
        if (!box.hidden) { try { rows[i].scrollIntoView({ block: 'nearest', behavior: 'smooth' }); } catch (e) {} }
        sayLine(l, i, rate(), () => { i++; nx(); });
      };
      nx();
    };
    pb.addEventListener('click', () => { if (play) { stop(); mark(-1); pb.textContent = '▶ Nghe lại'; return; } playFrom(0); });

    // câu hỏi
    const qs = E('div', 'rd-qs');
    qs.appendChild(E('h3', 'rd-qs-h', '❓ Câu hỏi'));
    if (l.lv >= 3) qs.appendChild(E('div', 'rv-note', 'Not Given = hội thoại không nhắc tới thông tin này.'));
    const ans = {};
    l.q.forEach((q, qi) => {
      const c = E('div', 'tense-card rd-q');
      const qh = E('div', 'rd-q-h'); qh.appendChild(E('span', 'rd-q-n', String(qi + 1))); qh.appendChild(E('span', 'rd-q-t', q.q)); c.appendChild(qh);
      const os = E('div', 'rd-opts'), fb = E('div', 'gx-fb'); fb.hidden = true;
      opts(q).forEach((o, oi) => {
        const b = E('button', 'gx-opt', (q.k === 'mc' ? 'ABCD'[oi] + '. ' : '') + o); b.type = 'button';
        b.addEventListener('click', () => {
          if (ans[qi] != null) return;
          ans[qi] = oi; const ok = oi === q.a;
          os.querySelectorAll('.gx-opt').forEach((x, j) => { x.disabled = true; if (j === q.a) x.classList.add('ok'); else if (j === oi) x.classList.add('bad'); });
          fb.hidden = false; fb.className = 'gx-fb ' + (ok ? 'ok' : 'bad'); fb.innerHTML = '';
          fb.appendChild(E('div', 'gx-fb-t', ok ? '✓ Chính xác!' : '✗ Chưa đúng'));
          fb.appendChild(E('div', 'gx-why ' + (ok ? 'ok' : 'bad'), q.e));
          const line = l.lines[q.ev];
          if (line) {
            const sh = E('button', 'btn-ghost rd-show', '🔊 Nghe lại câu chứa đáp án'); sh.type = 'button';
            sh.addEventListener('click', () => { box.hidden = false; tr.textContent = '🙈 Ẩn lời thoại'; playFrom(q.ev, q.ev); try { rows[q.ev].scrollIntoView({ behavior: 'smooth', block: 'center' }); } catch (e) {} });
            fb.appendChild(sh);
            fb.appendChild(E('div', 'gx-why soft', `${l.who[line[0]][0]}: “${line[1]}”`));
          }
          try { if (window.actLog) actLog('l'); } catch (e) {}
          try {
            const mk = 'ls|' + l.id + '|' + qi;
            if (ok) { if (window.mkOk) window.mkOk(mk); }
            else if (window.mkAdd) window.mkAdd({ k: mk, src: 'ls', cat: LV[l.lv - 1] + ' · ' + l.t, mode: 'mc', p: q.q, opts: opts(q), a: [opts(q)[q.a]], right: opts(q)[q.a], wrong: o, hint: line ? '“' + line[1] + '”' : '', why: q.e });
          } catch (e) {}
          if (Object.keys(ans).length === l.q.length) finish();
        });
        os.appendChild(b);
      });
      c.appendChild(os); c.appendChild(fb); qs.appendChild(c);
    });
    root.appendChild(qs);
    const res = E('div', 'rd-res'); root.appendChild(res);
    function finish() {
      const n = l.q.filter((q, i) => ans[i] === q.a).length, pct = Math.round(n / l.q.length * 100);
      const p2 = prog[l.id] || (prog[l.id] = {});
      p2.last = pct; p2.best = Math.max(p2.best || 0, pct); p2.n = (p2.n || 0) + 1; p2.t = Date.now(); p2.times = times; save();
      res.innerHTML = '';
      const c = E('div', 'tense-card gx-score ' + (pct >= 75 ? 'ok' : pct >= 50 ? 'mid' : 'bad'));
      c.appendChild(E('div', 'gx-score-t', 'Kết quả'));
      c.appendChild(E('div', 'gx-score-big', `${n}/${l.q.length}`));
      c.appendChild(E('div', 'gx-score-sub', `${pct}% · tốt nhất ${p2.best}%` + (times ? ` · nghe ${times} lần` : '')));
      c.appendChild(E('div', 'gx-score-msg', pct === 100 ? 'Tai bạn rất tốt! Thử bật lời thoại và nói theo từng câu để luyện phát âm.' : pct >= 75 ? 'Tốt lắm! Nghe lại câu chứa đáp án ở những câu sai.' : 'Hãy bật lời thoại, nghe lại từng câu và tra các từ chưa biết, rồi nghe lại không nhìn chữ.'));
      const row = E('div', 'rd-res-act');
      const again = E('button', 'btn-ghost', '↻ Nghe lại từ đầu'); again.type = 'button'; again.addEventListener('click', () => { lesson(l); top(); });
      row.appendChild(again);
      const nxl = LS_DIALOGS[LS_DIALOGS.indexOf(l) + 1];
      if (nxl) { const b = E('button', 'btn-primary', 'Bài tiếp: ' + nxl.t + ' →'); b.type = 'button'; b.addEventListener('click', () => { lesson(nxl); top(); }); row.appendChild(b); }
      c.appendChild(row); res.appendChild(c);
      try { c.scrollIntoView({ behavior: 'smooth', block: 'center' }); } catch (e) {}
    }
  }
  window.lsHome = home;
  window.lsOpen = id => { const l = LS_DIALOGS.find(x => x.id === id); if (l) lesson(l); };
})();


